var suggestions=document.getElementById('suggestions'),userinput=document.getElementById('userinput');document.addEventListener('keydown',inputFocus);function inputFocus(a){a.keyCode===191&&(a.preventDefault(),userinput.focus()),a.keyCode===27&&(userinput.blur(),suggestions.classList.add('d-none'))}document.addEventListener('click',function(a){var b=suggestions.contains(a.target);b||suggestions.classList.add('d-none')}),document.addEventListener('keydown',suggestionFocus);function suggestionFocus(b){const d=suggestions.querySelectorAll('a'),e=[...d],a=e.indexOf(document.activeElement);let c=0;b.keyCode===38?(b.preventDefault(),c=a>0?a-1:0,d[c].focus()):b.keyCode===40&&(b.preventDefault(),c=a+1<e.length?a+1:a,d[c].focus())}(function(){var b=new FlexSearch({preset:'score',cache:!0,doc:{id:'id',field:['title','description','content'],store:['href','title','description']}}),c=[{id:0,href:"/blog/3262080571/",title:"Wsl2 Linux 子系统的导入与导出",description:"记录 WSL 2 中 Debian 的导出与异名导入流程，涵盖备份校验、恢复验证、导入发行版默认用户设置，以及核验后可选的旧实例注销。",content:"适用范围：已能正常运行 Debian 的 Windows 10/11 + WSL 2。下列 wsl 命令在 Windows PowerShell 中执行；发行版名称以 wsl --list --verbose 为准，路径仅为示例。/etc/wsl.conf 的 [user] 设置要求 Windows Build 18980 或更高版本，参见 Microsoft WSL 配置文档。本次校订按官方文档核对命令，未进行真实发行版的导入或注销演练。\n恢复顺序是：保留原 Debian，导出备份，使用新名称 Debian-Restore 导入并验证，最后才考虑是否注销旧实例。\n  查看实例并停止待导出的 Debian\n先保存文件并退出正在运行的程序，停止实例会中断其中的进程。\nwsl --list --verbose wsl --terminate Debian  如确实需要停止所有发行版，可以用 wsl --shutdown；它会影响其他正在运行的 WSL 实例。本例只停止 Debian。\n  导出并检查归档\n确保 D 盘有足够空间，且下面的备份文件名未被占用，不要覆盖已有的唯一备份。\nwsl --export Debian \u0026quot;D:\\Debian.tar\u0026quot; Get-Item \u0026quot;D:\\Debian.tar\u0026quot; tar -tf \u0026quot;D:\\Debian.tar\u0026quot;  确认导出命令成功、文件非空且归档能列出内容；这仍不能代替下一步的实际恢复验证。保留此归档以及原实例，不要先执行 --unregister。\n  导入为一个新实例\n先确认 Debian-Restore 未出现在实例列表中，安装目录应为新的空目录，不要指向原实例的数据目录。以下命令显式使用 WSL 2：\nNew-Item -ItemType Directory -Path \u0026quot;D:\\WSL\\Debian-Restore\u0026quot; wsl --import Debian-Restore \u0026quot;D:\\WSL\\Debian-Restore\u0026quot; \u0026quot;D:\\Debian.tar\u0026quot; --version 2 wsl --list --verbose wsl -d Debian-Restore -u root -- cat /etc/os-release  预期列表同时保留 Debian 和 Debian-Restore，新实例的 VERSION 为 2，且能输出 Debian 的系统信息。命令语法参见 Microsoft WSL 导入、导出说明。\n  设置导入实例的默认登录用户\nDebian config --default-user ... 是发行版启动器的命令，不能用于没有独立启动器的导入实例。改用新实例内部的 /etc/wsl.conf。\n将下文的 yourname 换成已有的 Linux 用户名，先核对用户存在：\nwsl -d Debian-Restore -u root -- id yourname wsl -d Debian-Restore -u root  若该用户不存在，先在这个新 Debian 的 root 终端中创建，例如运行 adduser yourname；创建完成后再配置默认用户。编辑新实例内的 /etc/wsl.conf，保留原有其他配置，将下列内容合并到唯一的 [user] 节：\n[user] default=yourname  保存后退出 Linux 终端，回到 PowerShell 关闭并重启新实例，使配置生效：\nwsl --terminate Debian-Restore wsl -d Debian-Restore -- whoami wsl -d Debian-Restore -- ls -la /home/yourname  whoami 应输出所设置的用户名。继续核对项目文件、用户权限、所需工具和日常应用是否正常；仅能启动终端不代表恢复已完整验证。\n  可选：验证完成后处理旧实例\n可以一直保留原 Debian。仅在新实例的关键数据、权限和应用均已核验，另有可恢复备份，而且确认不再需要旧实例时，才手动考虑下面的注销命令：\n# 仅针对确认不再需要的旧 Debian；不要注销 Debian-Restore wsl --unregister Debian  注销会永久删除该实例关联的数据、软件和配置，无法通过重新安装自动找回；它不是导入新实例的必要步骤，详见官方注销说明。\n  "},{id:1,href:"/blog/532834567/",title:"在 HTTPS 端口使用 SSH",description:"整理 GitHub SSH 连接受限时通过 443 端口连接的配置笔记，涉及连通性测试、仓库克隆、SSH 配置文件与已知主机指纹检查。",content:"当网络阻断默认的 SSH 22 端口时，可以尝试 GitHub.com 提供的 443 端口 SSH 服务。这里传输的仍是 SSH 协议，使用的主机名是 ssh.github.com；它不是把 SSH 请求转换成 HTTPS，强制使用 HTTP 代理的网络仍可能无法连接。\n适用环境 适用于安装了 Git 和 OpenSSH 客户端的 Linux、macOS 或 Windows，且已经把对应公钥添加到 GitHub 账户。以下命令可在终端或 PowerShell 中执行；Windows OpenSSH 的配置文件通常为 %USERPROFILE%\\.ssh\\config，Linux/macOS 为 ~/.ssh/config。\n本文针对 GitHub.com。GitHub Enterprise Server，以及具有数据驻留功能的 Enterprise Cloud，不应直接套用这个入口；以 GitHub 当前支持范围为准。\n先测试 443 端口 ssh -T -p 443 git@ssh.github.com  首次连接时，先把主机指纹与 GitHub 官方指纹列表核对，再决定是否信任。不要通过关闭 StrictHostKeyChecking 绕过核验，也不要仅凭 IP 地址判断主机身份。\n认证成功时会看到包含下列内容的提示，USERNAME 是实际认证的账户名：\nYou've successfully authenticated, but GitHub does not provide shell access.  GitHub 不提供交互式 shell，因此这个测试即使认证成功也可能返回退出码 1。连接超时通常需要检查网络、代理或防火墙；Permission denied (publickey) 则表示应检查 SSH 密钥和账户授权，不能只靠切换端口解决。\n显式使用 443 克隆 将 OWNER 和 REPOSITORY 替换为实际仓库拥有者和名称：\ngit clone ssh://git@ssh.github.com:443/OWNER/REPOSITORY.git  注意主机名必须完整写为 ssh.github.com，而不是 ssh. 或端口 443 上的 github.com。\n为 github.com 配置默认入口 编辑已有的 SSH 配置文件，合并以下配置段；不要覆盖文件里的其他主机设置。如果已有匹配 github.com 的配置，应检查顺序，避免先出现的选项覆盖预期行为。\nHost github.com HostName ssh.github.com Port 443 User git  之后可以继续使用常见的 git@github.com:OWNER/REPOSITORY.git 地址。\n验证配置与仓库访问 先检查 OpenSSH 实际解析的配置，这一步不建立网络连接：\nssh -G github.com  输出中应包含 hostname ssh.github.com、port 443 和 user git。再测试认证和仓库读取：\nssh -T git@github.com git ls-remote git@github.com:OWNER/REPOSITORY.git HEAD  第二条命令应返回仓库 HEAD 的提交 ID 与引用名，且无需创建本地克隆。如果 ssh 测试正常但 Git 仍失败，检查 Git 是否通过 core.sshCommand、GIT_SSH_COMMAND 或另一个 SSH 客户端使用了不同配置。\n本次维护使用 Windows OpenSSH 9.5p2 和独立测试配置，核对官方 Ed25519 指纹后启用严格主机检查，成功通过 443 端口认证，并用 git ls-remote 读取本站仓库的 HEAD。未修改已有 SSH 配置；这个结果不代表任意网络、代理和账户都能直接连通。\n"},{id:2,href:"/blog/429417542/",title:"MySQL8 InnoDB 数据恢复",description:"记录 MySQL 8 InnoDB 表空间恢复笔记，涉及重建表结构、处理 .ibd 文件、设置文件权限，以及丢弃和导入表空间等操作。",content:"硬盘损坏后，如果仍保留完整的 InnoDB 独立表空间文件，可以尝试把数据导入重建的空表。这里整理的是表空间导入流程，不是对任意损坏 .ibd 文件都能成功的恢复保证。\n适用环境与前提  目标为 MySQL 8.0，使用 InnoDB 独立表空间（innodb_file_per_table=ON）；来源和目标版本、页大小以及表结构须满足 MySQL 导入表空间的要求。演练时使用相同版本。 保存原始文件的只读备份，在新的恢复实例、空表中操作。DISCARD TABLESPACE 会丢弃目标空表的表空间文件，所以应先 DISCARD，再复制恢复文件，不能反过来。 必须知道原表的完整 DDL，包括列顺序、类型、索引、字符集、排序规则和行格式。下面的 notes 只是演练表，不能用于导入结构不同的业务表。 本文的简化步骤针对非分区、未加密、无外键关联和无全文索引的普通表；其他情况应按官方对应流程处理。仅有文件名相同并不足以恢复。  Linux 文件复制命令假设数据库系统用户为 mysql，实际服务用户和路径以目标实例为准。SQL 在 MySQL 客户端执行，Shell 命令在操作系统终端执行，两者不要混用。\n1. 检查版本与真实数据目录 mysql -u root -p  SELECT VERSION(), @@datadir, @@innodb_file_per_table, @@innodb_page_size;  数据文件位于 @@datadir 对应目录，不一定在 MySQL 程序安装目录中。先核对页大小与来源一致，并确认独立表空间已启用。\n如果来源实例还可读，优先取得 SHOW CREATE TABLE 结果。需要导出一致的物理副本时，在来源连接执行 FLUSH TABLES notes FOR EXPORT，保持连接和锁，在另一终端复制 .ibd、.cfg 后再 UNLOCK TABLES。不要把运行中的普通文件复制当成一致备份。\n2. 在恢复库重建一致的空表 以下 DDL 是可复现的演练示例。恢复真实表时，必须替换为原表的完整 DDL，且恢复库应预先确认为空的专用数据库。\nCREATE DATABASE recovery_lab CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci; USE recovery_lab; CREATE TABLE notes ( id BIGINT UNSIGNED NOT NULL, body VARCHAR(255) NOT NULL, PRIMARY KEY (id) ) ENGINE=InnoDB ROW_FORMAT=DYNAMIC DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;  选择数据库的命令是 USE recovery_lab;，不是 user。不在 SQL 中原样填写 \u0026lt;table_name\u0026gt; 之类的占位符。\n3. 先丢弃目标空表的表空间 在恢复库的 MySQL 连接执行：\nUSE recovery_lab; ALTER TABLE notes DISCARD TABLESPACE;  确认这是刚创建的空表，且原始恢复文件位于数据目录以外的备份位置。此时目标的 notes.ibd 被移除，这是预期行为。\n4. 再复制备份文件并修正权限 以下为 Linux Bash 示例。把 DATADIR 改为上面查询得到的目录，BACKUP 改为恢复文件副本的位置；每次只处理一张表。\nDATADIR=/var/lib/mysql BACKUP=/backup/recovered sudo cp \u0026quot;$BACKUP/notes.ibd\u0026quot; \u0026quot;$DATADIR/recovery_lab/notes.ibd\u0026quot; sudo chown mysql:mysql \u0026quot;$DATADIR/recovery_lab/notes.ibd\u0026quot; sudo chmod 660 \u0026quot;$DATADIR/recovery_lab/notes.ibd\u0026quot; if [ -f \u0026quot;$BACKUP/notes.cfg\u0026quot; ]; then sudo cp \u0026quot;$BACKUP/notes.cfg\u0026quot; \u0026quot;$DATADIR/recovery_lab/notes.cfg\u0026quot; sudo chown mysql:mysql \u0026quot;$DATADIR/recovery_lab/notes.cfg\u0026quot; sudo chmod 660 \u0026quot;$DATADIR/recovery_lab/notes.cfg\u0026quot; fi  如只剩 .ibd 而没有 .cfg，MySQL 可以在部分条件下尝试导入，但不会进行同样的元数据核对。尤其不能直接套用到含 ALGORITHM=INSTANT 加列或删列历史的表；无法确认原结构和修改历史时，应先查阅官方限制，不要在唯一原件上试错。\n5. 导入并检查结果 回到恢复库的 MySQL 连接：\nUSE recovery_lab; ALTER TABLE notes IMPORT TABLESPACE; SHOW WARNINGS;  CHECK TABLE recovery_lab.notes; SELECT COUNT(*) FROM recovery_lab.notes; SELECT id, body FROM recovery_lab.notes ORDER BY id LIMIT 10;  CHECK TABLE 应返回正常状态。还需将行数、主键、抽样记录及业务约束与备份记录核对，不能仅凭 IMPORT 没报错或读到一行就认定完整恢复。导入失败时保留日志和原始备份副本，不要反复覆盖它。\n确认数据正确后，导出逻辑备份，后续在正常实例中恢复：\nmysqldump -u root -p --single-transaction --no-tablespaces recovery_lab notes \u0026gt; recovered-notes.sql  演练与验证范围 可在隔离实例中按相同 DDL 创建来源表：先把第 2 步 DDL 的库名替换为 recovery_source 执行，再写入两条已知记录并锁定导出。\nINSERT INTO recovery_source.notes (id, body) VALUES (1, '演练A'), (2, '演练B'); FLUSH TABLES recovery_source.notes FOR EXPORT;  保持这个连接，在另一终端把来源数据目录中 recovery_source/notes.ibd 和 notes.cfg 复制到备份目录；复制完成后，在原连接执行：\nUNLOCK TABLES;  再在目标 recovery_lab 中按第 2～5 步恢复。预期行数为 2，两条记录与来源逐项相同，并能继续插入新记录。\n本次维护使用独立的 Windows MySQL 8.0.44 实例，验证了带 .cfg 的导入，以及这张没有 INSTANT 列变更历史的普通表不带 .cfg 的导入，核对记录、恢复后写入和逻辑导出均通过，实例已停止。Linux 的 chown/chmod 仅作为对应平台操作说明。磁盘损坏、加密表、分区表及未知结构文件不在这个正常文件演练的验证范围内。\n参考：导入 InnoDB 表、移动或复制 InnoDB 表。\n"},{id:3,href:"/blog/3082362680/",title:"JS获取Shadow DOM中closes 节点",description:"记录通过 Tampermonkey 覆盖 attachShadow 的脚本示例，将后续创建的 Shadow DOM 改为 open 模式，便于检查相关节点。",content:"安装 Tampermonkey 后，可以在自己的测试页面中提前替换 attachShadow，将后来经该方法创建的 Shadow Root 改为 open，方便调试。\n执行时机与适用范围 脚本必须在页面调用 attachShadow 之前、并在页面自己的 JavaScript 主执行环境（MAIN_WORLD，不是扩展的隔离环境）中运行。document-start 只是请求尽早注入；扩展权限、浏览器版本或 CSP 等仍可能影响实际时机和执行环境，不能保证赶在所有页面脚本之前。\n下面是 Tampermonkey 4.18+ 的元信息示例。把 @match 的 https://example.com/* 换成自己要调试的页面范围，确认扩展获得该站点权限，再重新加载测试页。@sandbox raw 请求页面执行环境；若实际回退到了其他沙箱，需要先核实执行环境，单纯修改隔离环境的 Element.prototype 不会达到这里的目的。\n// ==UserScript== // @name Shadow DOM open-mode debugging // @namespace https://clannad.icu/ // @version 1.0 // @match https://example.com/* // @run-at document-start // @sandbox raw // @grant none // ==/UserScript== (function () { 'use strict'; const prototype = Element.prototype; const marker = Symbol.for('clannadzsy.shadow-open-debug'); const originalAttachShadow = prototype.attachShadow; if (originalAttachShadow[marker]) return; function attachShadowForDebug(options) { if (options === null || !['object', 'function'].includes(typeof options)) { return Reflect.apply(originalAttachShadow, this, arguments); } // 仅覆盖 mode；其余字段仍从原 options 读取，保留 getter 的接收者。 const forwarded = new Proxy({}, { get: function (_target, key) { return key === 'mode' ? 'open' : Reflect.get(options, key, options); } }); const args = Array.from(arguments); args[0] = forwarded; return Reflect.apply(originalAttachShadow, this, args); } Object.defineProperty(attachShadowForDebug, marker, { value: true }); prototype.attachShadow = attachShadowForDebug; }());  原方法保存在闭包中，通过 Reflect.apply 保留宿主元素的 this；重复安装这个脚本不会不断包裹自身。delegatesFocus、slotAssignment 等参数仍按原值读取，不会因强制 mode 而全部丢失。该调试 hook 会改变页面组件的封装行为，其他脚本再次替换该方法时也可能覆盖它。\n已经创建的 closed root 不会改变 安装之前已经创建的 closed root，其宿主的 shadowRoot 仍为 null，不能追溯地变成 open。保存原先 attachShadow 返回引用的代码仍可能访问那个 root，但本脚本无法凭空恢复已经丢失的引用；声明式 Shadow DOM 等未调用此包装方法的创建路径也不在其作用范围内。\n本次在 Chrome 无头浏览器的本地 about:blank 测试页验证：先创建的 closed root 保持不可从 host.shadowRoot 读取；安装脚本后创建的 root 为 open，能够查询其内部节点，而且 delegatesFocus: true 保留。没有向用户实际网页注入脚本，也没有把这个测试当作 Tampermonkey 在所有站点的注入时机保证。\n参考 MDN：attachShadow、Tampermonkey：执行时机与执行环境。\n"},{id:4,href:"/blog/1190727728/",title:"WindMouse，一种生成类人鼠标运动的算法",description:"收录 WindMouse 算法的 Python 实现与 Matplotlib 绘图示例，展示鼠标移动轨迹，并比较风力、重力等参数对路径形态的影响。",content:"运行环境与示例范围 下面保留原作者的 WindMouse 算法和默认参数。函数使用赋值表达式，需要 Python 3.8 或更新版本；本次在 Python 3.12.14、NumPy 2.3.5、Matplotlib 3.10.7 下验证。可在 Python 3.12 的独立环境执行 python -m pip install \u0026quot;numpy==2.3.5\u0026quot; \u0026quot;matplotlib==3.10.7\u0026quot;。\n示例只记录坐标并绘图，不调用系统鼠标接口，也不模拟真实用户输入。固定随机种子便于复现本次输入；它不能证明任意参数下都会收敛，也不能证明生成轨迹与真实人的行为等价。\nWindMouse 将下面完整函数保存为 wind_mouse.py，后面的绘图脚本会从中导入。\nimport numpy as np sqrt3 = np.sqrt(3) sqrt5 = np.sqrt(5) def wind_mouse(start_x, start_y, dest_x, dest_y, G_0=9, W_0=3, M_0=15, D_0=12, move_mouse=lambda x,y: None): ''' WindMouse algorithm. Calls the move_mouse kwarg with each new step. Released under the terms of the GPLv3 license. G_0 - magnitude of the gravitational fornce W_0 - magnitude of the wind force fluctuations M_0 - maximum step size (velocity clip threshold) D_0 - distance where wind behavior changes from random to damped ''' current_x,current_y = start_x,start_y v_x = v_y = W_x = W_y = 0 while (dist:=np.hypot(dest_x-start_x,dest_y-start_y)) \u0026gt;= 1: W_mag = min(W_0, dist) if dist \u0026gt;= D_0: W_x = W_x/sqrt3 + (2*np.random.random()-1)*W_mag/sqrt5 W_y = W_y/sqrt3 + (2*np.random.random()-1)*W_mag/sqrt5 else: W_x /= sqrt3 W_y /= sqrt3 if M_0 \u0026lt; 3: M_0 = np.random.random()*3 + 3 else: M_0 /= sqrt5 v_x += W_x + G_0*(dest_x-start_x)/dist v_y += W_y + G_0*(dest_y-start_y)/dist v_mag = np.hypot(v_x, v_y) if v_mag \u0026gt; M_0: v_clip = M_0/2 + np.random.random()*M_0/2 v_x = (v_x/v_mag) * v_clip v_y = (v_y/v_mag) * v_clip start_x += v_x start_y += v_y move_x = int(np.round(start_x)) move_y = int(np.round(start_y)) if current_x != move_x or current_y != move_y: #This should wait for the mouse polling interval move_mouse(current_x:=move_x,current_y:=move_y) return current_x,current_y  Example 将下面代码保存为同目录下的 plot_wind_mouse.py，运行 python plot_wind_mouse.py，输出图片 wind_mouse_examples.png。Agg 后端无需图形窗口，适合本地脚本验证；随机种子使用原算法所调用的 NumPy 全局随机状态。\nimport matplotlib import numpy as np matplotlib.use('Agg') # 必须放在导入 pyplot 之前 import matplotlib.pyplot as plt from wind_mouse import wind_mouse np.random.seed(20240317) fig = plt.figure(figsize=[13,13]) plt.axis('off') for y in np.linspace(-200,200,25): points = [] def record(x, y): if len(points) \u0026gt;= 10000: raise RuntimeError('trajectory exceeded the example step limit') points.append([x, y]) end_x, end_y = wind_mouse(0, y, 500, y, move_mouse=record) points = np.asarray(points) assert points.ndim == 2 and points.shape[1] == 2 assert np.isfinite(points).all() # 算法在连续坐标距离目标小于 1 时停止，回调坐标还经过取整。 assert np.hypot(end_x - 500, end_y - y) \u0026lt; 2 plt.plot(*points.T) plt.xlim(-50,550) plt.ylim(-250,250) fig.savefig('wind_mouse_examples.png') plt.close(fig) print('25 finite trajectories saved')  固定种子的 25 条轨迹均通过有限步数、坐标有限性与终点距离检查。上面的回调步数上限仅用于中断异常示例；原函数本身没有迭代上限。不合理的输入、非正的引力或其他参数组合不在此验证范围，不能直接当作生产环境的安全保证。\n这些轨迹可与原作者文章中的人类移动示例进行视觉比较。这里使用 WindMouse 的默认参数，这些参数不一定适合每个用例，可以根据需要调整并观察不同的结果。例如，将风参数设置为等于重力参数，通常会生成更曲折的路径。下图保留原文的高风力示例，并非本次固定种子验证重新生成的结果。\n转载: WindMouse "},{id:5,href:"/blog/3231606058/",title:"The Golang Chronicles From Ai",description:"A fictional steampunk adventure in which Alaric, Elara and Thorne pursue the Golang Codex, face the Phantom Coder and uncover the Clockwork Conspiracy in Devoria.",content:"Title: \u0026ldquo;The Golang Chronicles\u0026rdquo;\nChapter 1: The Mysterious Codex\nIn the bustling city of Devoria, where the clatter of steam-powered machines filled the air, lived a young prodigy named Alaric. He was known throughout the city as the most brilliant programmer, his skills unmatched in the world of technology. Alaric had an insatiable hunger for knowledge and was always seeking the next great challenge.\nOne fateful day, Alaric received a cryptic message on his antique computer, a relic from a bygone era. The message was a string of seemingly random characters, but Alaric\u0026rsquo;s keen eye detected a pattern hidden within. It was a challenge, an invitation to a secret competition known only as \u0026ldquo;The Golang Challenge.\u0026rdquo;\nWith curiosity burning in his heart, Alaric delved into the challenge, unraveling its intricate layers of puzzles and enigmas. As he progressed, he discovered that The Golang Challenge was not just a game; it was a quest for a legendary artifact, the Golang Codex, said to hold the power to control the very fabric of reality.\nChapter 2: The Enigmatic Rival\nAs Alaric delved deeper into the challenge, he found himself entangled in a web of intrigue and rivalry. His foremost competitor was a shadowy figure known as \u0026ldquo;The Phantom Coder.\u0026rdquo; This enigmatic adversary matched Alaric\u0026rsquo;s every move, leaving behind only cryptic messages and intricate lines of code as clues.\nAlaric\u0026rsquo;s quest led him to all corners of Devoria, from the labyrinthine catacombs beneath the city to the soaring spires of the Clockwork Citadel. Along the way, he encountered a cast of memorable characters, each with their own motives and secrets. Among them was Elara, a brilliant inventor with a mysterious past, and Thorne, a grizzled hacker with a heart of gold.\nChapter 3: The Clockwork Conspiracy\nAs Alaric and his newfound allies raced against time to solve the final puzzle, they uncovered a sinister plot that threatened not only Devoria but the entire world. The Golang Codex was not just a source of power; it held the key to unleashing a cataclysmic force that could bring about the downfall of civilization as they knew it.\nThe Phantom Coder\u0026rsquo;s true identity was revealed, and the battle between genius programmers escalated into a high-stakes showdown. With the fate of the world hanging in the balance, Alaric had to push the limits of his abilities and forge unlikely alliances to thwart the Clockwork Conspiracy.\nChapter 4: The Ultimate Code\nIn a climactic battle of wits and ingenuity, Alaric, Elara, and Thorne confronted the true mastermind behind the Golang Challenge and the Clockwork Conspiracy. The final puzzle was a code so intricate, so powerful, that it could rewrite the very laws of reality.\nAs lines of code clashed with steam and gears, as algorithms collided with arcane magic, the fate of Devoria and the world was decided. It was a battle not just of programming prowess but of the human spirit, of determination, and of the power of unity in the face of overwhelming odds.\nIn the end, it was not just the Golang Codex that was unlocked but the untapped potential within Alaric, Elara, and Thorne. They discovered that the true power of Golang lay not in controlling the world but in using their skills for the betterment of humanity.\nEpilogue: The Legacy of Golang\nThe Golang Codex was sealed away, its power safeguarded for future generations. Alaric, Elara, and Thorne became legends, their names etched into the annals of Devoria\u0026rsquo;s history as the heroes who saved the world.\nBut the world of technology and adventure continued to evolve, and new challenges awaited. As they looked to the horizon, Alaric, Elara, and Thorne knew that they were bound by the code of curiosity, the code of discovery, and the code of friendship.\nAnd so, the legacy of Golang lived on, a testament to the endless possibilities of the human imagination and the boundless potential of those who dared to dream and code.\n[End of \u0026ldquo;The Golang Chronicles\u0026rdquo;]\n"},{id:7,href:"/blog/1539748842/",title:"提高 Golang 并发编程能力的必备利器：深入学习 sync.Cond 类型",description:"整理 Go sync.Cond 的条件变量用法，介绍 Wait、Signal、Broadcast 与互斥锁的配合，并记录初始化等待和生产者消费者示例。",content:"Go 的 sync.Cond 用于等待共享状态满足某个条件。条件由程序自己的变量表达，通知只是提醒等待者重新检查变量，并不会保存一份可供以后消费的“信号”。下面保留初始化等待和生产者消费者两个用例，修正原转载中的源码说明与示例。\n适用环境：示例仅依赖标准库，在 Go 1.23.3、Windows/amd64 验证。每个 package main 代码块分别保存为 main.go，在空目录运行 go run main.go；程序都能自行结束，不需要访问网络。\n1. 条件变量与互斥锁 sync.NewCond 接收实现 sync.Locker 的对象，通常使用 *sync.Mutex。读取或修改条件，以及调用 Wait 时，必须持有同一把锁。Cond 第一次使用后不能复制。\nWait 会原子地释放 cond.L 并挂起当前 goroutine；被通知后，它会重新取得该锁才返回。调用方必须先加锁，Wait 本身不会替调用方完成第一次加锁。若使用 RWMutex，必须明确传入的是写锁还是 RLocker() 返回的读锁，不能混用加解锁方式；下面统一用 Mutex。\n等待初始化完成 package main import ( \u0026quot;fmt\u0026quot; \u0026quot;sync\u0026quot; ) func main() { var mu sync.Mutex cond := sync.NewCond(\u0026amp;mu) ready := false go func() { // 在这里完成初始化，再在锁内发布状态。 mu.Lock() ready = true cond.Signal() mu.Unlock() }() mu.Lock() for !ready { cond.Wait() } fmt.Println(\u0026quot;Initialization completed\u0026quot;) mu.Unlock() }  验证：输出 Initialization completed 后退出。即使初始化 goroutine 先运行、Signal 发生时还没有等待者，主 goroutine 也会因为 ready 已为真而直接继续，不会丢失初始化状态。\n这里使用 for，因为等待者重新取得锁时，其他 goroutine 可能已经再次改变条件。Go 的 Wait 不会无缘无故返回；循环检查是为了确认共享条件仍然成立，不能将一次通知等同于条件永久成立。\nSignal 与 Broadcast  Signal 唤醒当前等待的一个 goroutine；没有等待者时不保存通知，也不保证被唤醒者优先取得锁。 Broadcast 唤醒当前所有等待者。它们仍要依次重新取得锁、检查条件。 官方 API 允许调用 Signal、Broadcast 时持有或不持有 cond.L；这不等于可以无锁读写条件。本文在锁内修改状态并通知，便于把同步规则放在一起。  如果多个等待者都在等同一个只会从假变真的初始化状态，应使用 Broadcast；只 Signal 一次可能让其余等待者一直睡眠。对于单次完成事件，关闭一个 channel 往往更简单。\n2. 实现原理的边界 Go 1.23.3 的 sync.Cond 内部有独立的 notifyList，Wait 大致经过“登记等待票据、解锁、等待通知、重新加锁”几个阶段，通知使用运行时的等待设施，而不是循环调用 runtime.Gosched 忙等。\n原文给出的 wait{done,next,cond}、Mutex.notify 和 runtime.NotifyListNotify 不是该版本的标准库源码，且读写 done 的忙等示例缺少同步，已移除。内部字段与运行时函数是实现细节，应用程序应依赖公开的 Wait、Signal、Broadcast 行为。\n可通过已安装工具链的 go doc sync.Cond 和 $GOROOT/src/sync/cond.go 对照；线上参考 Go 1.23.3 Cond 文档与 Go 官方 Cond 源码。线上源码会随 Go 版本更新，应以自己的工具链版本为准。\n3. 有界生产者消费者队列 生产者等待“队列未满”，消费者等待“队列非空”。这两个条件使用同一把互斥锁，分别建立 notFull 与 notEmpty 两个 Cond，避免一个混合等待队列中的 Signal 唤醒错误类别的等待者。\n下面增加关闭状态：生产者完成后关闭队列，消费者取完剩余项后退出。关闭时广播唤醒两类等待者；生产者数量有限，主 goroutine 使用 WaitGroup 等待全部工作结束。\npackage main import ( \u0026quot;fmt\u0026quot; \u0026quot;sync\u0026quot; ) type Queue struct { items []int size int closed bool mu sync.Mutex notEmpty *sync.Cond notFull *sync.Cond } func NewQueue(size int) *Queue { if size \u0026lt;= 0 { panic(\u0026quot;queue size must be positive\u0026quot;) } q := \u0026amp;Queue{size: size, items: make([]int, 0, size)} q.notEmpty = sync.NewCond(\u0026amp;q.mu) q.notFull = sync.NewCond(\u0026amp;q.mu) return q } func (q *Queue) Put(item int) bool { q.mu.Lock() defer q.mu.Unlock() for len(q.items) == q.size \u0026amp;\u0026amp; !q.closed { q.notFull.Wait() } if q.closed { return false } q.items = append(q.items, item) q.notEmpty.Signal() return true } func (q *Queue) Get() (int, bool) { q.mu.Lock() defer q.mu.Unlock() for len(q.items) == 0 \u0026amp;\u0026amp; !q.closed { q.notEmpty.Wait() } if len(q.items) == 0 { return 0, false } item := q.items[0] q.items = q.items[1:] q.notFull.Signal() return item, true } func (q *Queue) Close() { q.mu.Lock() q.closed = true q.notEmpty.Broadcast() q.notFull.Broadcast() q.mu.Unlock() } func main() { q := NewQueue(5) var producers, consumers sync.WaitGroup var resultMu sync.Mutex count, total := 0, 0 for id := 0; id \u0026lt; 5; id++ { consumers.Add(1) go func() { defer consumers.Done() for { item, ok := q.Get() if !ok { return } resultMu.Lock() count++ total += item resultMu.Unlock() } }() } for id := 0; id \u0026lt; 3; id++ { producers.Add(1) go func(id int) { defer producers.Done() for n := 0; n \u0026lt; 10; n++ { if !q.Put(id*10 + n) { return } } }(id) } producers.Wait() q.Close() consumers.Wait() fmt.Printf(\u0026quot;consumed=%d sum=%d\\n\u0026quot;, count, total) }  验证：输出 consumed=30 sum=435 后退出；消费顺序由调度决定，不保证生产者间的顺序。该队列用于演示条件等待，切片队头移除并非固定内存的环形队列实现。需要取消、超时或不同业务策略时，应另外设计停止协议，不能直接给 Cond.Wait 添加一个超时参数。\n4. 验证与注意事项 两个完整程序分别执行 go run main.go。支持 race detector 的平台并安装其所需 C 工具链后，可分别运行 go run -race main.go；检测通过也不能代替对条件循环和退出协议的检查。官方说明见 Data Race Detector。\n共享条件始终由关联锁保护；等待使用 for；关闭时唤醒可能永久等待的 goroutine；程序退出前等待工作完成。这些是示例的正确性前提，无需依赖运行时队列的具体布局。\n转载与校订 原作者：金刀大菜牙\n原文链接：https://juejin.cn/post/7228755069017309240\n来源：稀土掘金。保留原文主题与署名，以上示例和实现说明已按官方 API 校订。原文著作权归原作者所有，商业转载请联系作者获得授权，非商业转载请注明出处。\n"},{id:8,href:"/blog/3640029440/",title:"解决 Android 7 及以上的安卓系统模拟器, 无法抓包 https 请求",description:"整理 Android 7 及以上系统和模拟器进行 HTTPS 抓包的证书配置笔记，涵盖 OpenSSL 证书格式处理、ADB 安装系统证书及 Charles 相关设置。",content:"Android 7.0+ 上，targetSdkVersion 为 24 及以上的应用默认只信任系统 CA，不再默认信任用户安装的 CA；旧 target 的默认策略不同，应用也可以自行配置。因而把 Charles、Fiddler 的 CA 装入“用户证书”后，部分应用仍会拒绝 HTTPS 连接。规则见 Android 官方 Network Security Configuration。\n本文保留系统 CA 的处理思路，只适用于自己控制的可 root 测试镜像；普通量产设备不保证支持 adb root。Android 14 起信任库还涉及 Conscrypt APEX，不能把向旧系统目录复制文件的步骤推广到所有 Android 版本。安装 CA 也不保证绕过应用或网络库自行实现的 TLS pinning。\n导出并转换代理 CA 从实际使用的抓包代理导出其 CA 证书。.cer 后缀并不能证明内容是 DER，要按文件实际格式选择下面一组命令；两组是替代方案。本次仅在 Windows、OpenSSL 1.1.1l 验证格式转换，不是建议继续使用这个旧版本部署生产服务。\nDER 格式证书 openssl x509 -inform DER -in proxy-ca.cer -subject_hash_old -noout openssl x509 -inform DER -in proxy-ca.cer -outform PEM -out hash.0  PEM 格式证书 openssl x509 -inform PEM -in proxy-ca.pem -subject_hash_old -noout openssl x509 -inform PEM -in proxy-ca.pem -outform PEM -out hash.0  把文件名中的 hash 换成第一条命令输出的八位哈希值。例如输出 abcd1234 时，文件名为 abcd1234.0；如果目标目录存在同名文件，先比较证书，不要直接覆盖，不同证书发生名称冲突时需按该信任库规则使用后续序号。\n输出应是纯 PEM，不加 -text，也不需要手工移动证书文本。可在本地检查其信息：\nopenssl x509 -inform PEM -in hash.0 -noout -subject -issuer -fingerprint -sha256  确认代理导出的证书与转换后的 SHA-256 指纹相同。subject_hash_old 是用于命名的旧 subject 哈希，不是证书的安全指纹。参数说明见 OpenSSL x509 文档。\n旧系统目录：仅限已确认可写的测试镜像 在一些较旧的可 root 测试镜像中，系统 CA 位于 /system/etc/security/cacerts/。下面是该前提成立时的操作示意，执行前需自行核对镜像版本、目录及同名文件；不是普通手机的通用步骤：\nadb root adb remount adb push hash.0 /system/etc/security/cacerts/hash.0 adb shell chown root:root /system/etc/security/cacerts/hash.0 adb shell chmod 0644 /system/etc/security/cacerts/hash.0 adb reboot  这些设备命令未在本次环境执行。若镜像不支持 root、remount 或目录不可写，应停止并查该镜像的说明；不能假设执行 su 或随意禁用验证就会成功。新镜像的分区、SELinux 与信任库实现也可能要求不同的安装方式。\nAndroid 官方 Conscrypt 说明指出 Android 14 起根信任证书同时存于 Conscrypt APEX 和系统分区，因此仅修改旧路径不构成已验证的 Android 14+ 方案。测试结束后应按测试镜像的恢复方式撤销更改。\n自有应用可以使用仅调试生效的信任配置 能修改自己 APK 时，可在 debug 变体中声明代理 CA，避免依赖系统目录。把纯 PEM 证书放到 src/debug/res/raw/proxy_ca.pem，在 src/debug/res/xml/debug_network_security_config.xml 写入：\n\u0026lt;?xml version=\u0026quot;1.0\u0026quot; encoding=\u0026quot;utf-8\u0026quot;?\u0026gt; \u0026lt;network-security-config\u0026gt; \u0026lt;debug-overrides\u0026gt; \u0026lt;trust-anchors\u0026gt; \u0026lt;certificates src=\u0026quot;@raw/proxy_ca\u0026quot; /\u0026gt; \u0026lt;/trust-anchors\u0026gt; \u0026lt;/debug-overrides\u0026gt; \u0026lt;/network-security-config\u0026gt;  在 src/debug/AndroidManifest.xml 中引用它；已有网络配置时需结合项目合并，不要覆盖正式版本的配置：\n\u0026lt;?xml version=\u0026quot;1.0\u0026quot; encoding=\u0026quot;utf-8\u0026quot;?\u0026gt; \u0026lt;manifest xmlns:android=\u0026quot;http://schemas.android.com/apk/res/android\u0026quot;\u0026gt; \u0026lt;application android:networkSecurityConfig=\u0026quot;@xml/debug_network_security_config\u0026quot; /\u0026gt; \u0026lt;/manifest\u0026gt;  debug-overrides 仅在应用 android:debuggable 为 true 时生效，通常由 debug 构建设置。平台网络安全配置会对使用这些调试信任锚的证书链按其调试规则处理 pinning；这不等同于能绕过任意应用自定义的校验。这里仅静态解析了 XML，未构建 APK、安装证书或在 Android 设备上验证。\n抓包验证 在 Charles 或 Fiddler 中启用目标域名的 HTTPS/SSL Proxying，确认应用实际经过该代理，并检查握手错误、证书链与目标域名是否匹配。若仍失败，应区分代理连通性、应用信任配置和自定义证书校验，而不是继续手工改写 PEM 文件内容。本次只验证了临时 CA 的 DER/PEM 转换、哈希及证书往返一致性。\n"},{id:9,href:"/blog/630506263/",title:"Golang并发时报错connection Reset by Peer",description:"区分 Go 并发请求中的连接重置与本地文件描述符耗尽，演示错误链分类，并说明 Linux 资源限制排查及验证边界。",content:"Go 并发请求中出现 connection reset by peer，说明连接被对端重置；对端也可能是代理、负载均衡器等中间节点。仅凭这段错误文字，无法判定是服务端策略、连接复用、应用行为还是某项资源限制。它不等同于本地文件描述符耗尽，不能直接得出“程序没问题，只需提高系统限制”的结论。\n先保留完整错误与请求条件 记录操作是拨号、读取还是写入，以及目标地址、并发数、超时、连接复用方式和服务端对应时间的日志。检查响应体是否关闭、客户端是否重复创建、请求是否有界，再做单变量对比。http.Client 和 Transport 适合复用；成功返回响应时应及时关闭 resp.Body，能读到 EOF 并关闭时才有利于连接复用。\n参考 Go 1.23.3 http.Client、Transport 与 net.OpError。自动重试还必须考虑请求是否幂等，不能无条件重复有副作用的请求。\n区分重置与本地资源耗尽 适用环境：下面只演示 Go 标准库错误链的识别方式，在 Go 1.23.3、Windows/amd64 验证；不发起网络请求，也不声称复现了服务器故障。保存为 main.go，运行 go run main.go。\npackage main import ( \u0026quot;errors\u0026quot; \u0026quot;fmt\u0026quot; \u0026quot;net\u0026quot; \u0026quot;syscall\u0026quot; ) func main() { // 人工构造错误链，验证分类逻辑；实际排查时替换为请求返回的 err。 reset := \u0026amp;net.OpError{Op: \u0026quot;read\u0026quot;, Net: \u0026quot;tcp\u0026quot;, Err: syscall.ECONNRESET} exhausted := fmt.Errorf(\u0026quot;open socket: %w\u0026quot;, syscall.EMFILE) fmt.Println(errors.Is(reset, syscall.ECONNRESET)) fmt.Println(errors.Is(exhausted, syscall.EMFILE)) var operation *net.OpError if errors.As(reset, \u0026amp;operation) { fmt.Println(operation.Op, operation.Net) } }  期望输出为 true、true、read tcp。错误码和包装形式与平台、调用路径有关；例如 Windows 的套接字错误可能使用 Winsock 错误码，应检查真实错误链，不能只匹配本例构造的一个值。errors.Is、errors.As 的用法见 Go 官方 errors 文档。\nLinux 文件描述符限制只是排查分支 原笔记中的 /etc/security/limits.conf、nofile、nproc 只适用于相应的 Linux 登录及服务管理环境。nofile 约束文件描述符，nproc 是另一项进程/线程相关限制；root 用户的默认值并非所有机器都固定为 4096。\n只有实际错误与进程占用情况表明文件描述符不足时，才检查并调整启动该程序的用户或服务限制。交互式 shell 可先用 ulimit -Sn、ulimit -Hn 查看自身的软硬限制，但服务进程可能由 systemd、容器或其他启动器设置，shell 的值不代表运行中服务的实际限制。\nsysctl -p 读取的是 sysctl 参数配置，不会把 limits.conf 的变更应用到已有进程。修改登录限制通常需要重新建立相应会话，服务需要按其启动器配置并重启，再核对进程的实际限制。不要把提高 nofile 当作所有连接重置的通用修复，更不要直接复制针对 root 的无限制配置。\n本次只验证上述无网络错误分类程序，未在 Linux 服务或真实远端上验证限制调整；最终原因仍需结合发生故障的客户端、服务端和网络证据判断。\n"},{id:10,href:"/blog/2494707647/",title:"[Python] 卖家精灵 Chrome 插件 Js 逆向",description:"记录卖家精灵 Chrome 插件的 JavaScript 分析过程，从扩展目录和查询请求入手，追踪 tk 参数生成逻辑与版本号处理，并附 Python 调用相关函数的代码示例。",content:"本文保留 2022 年对卖家精灵 Chrome 扩展 3.1.4 的分析过程。扩展 ID、截图、接口字段和版本派生常量均属于当时样本；整理后的代码只用于离线复现参数计算，不表示当前扩展、登录流程或第三方服务仍采用相同实现。文中的 e、t 是不同函数各自的局部形参，含义需要结合调用位置判断。\n以下 static 方法和接口调用是从扩展摘录的分析片段，不能单独作为脚本运行；第 6 步的三个普通函数才是可保存执行的 sellersprite.js。路径中的“用户名”为占位值，B00DQFGJR4 是当时分析用的固定 ASIN 样本，无需请求产品或私有接口即可验证计算结果。\n  chrome://version, 查看 个人资料路径\nC:\\Users\\用户名\\AppData\\Local\\Google\\Chrome\\User Data\\Default    打开插件所在文件夹: Extensions, 目录如下:\nC:\\Users\\用户名\\AppData\\Local\\Google\\Chrome\\User Data\\Default\\Extensions    chrome://extensions/ 查看卖家精灵插件 ID\nID：lnbmbgocenenhhhdojdielgnmeflbnfb    根据插件ID, 寻找对应的文件夹并使用编辑器打开\n  卖家精灵产品查询分析流程\n  URL分析\n  tk 参数分析\n  B00DQFGJR4 不变, 更改 tk 的值, 提示无法使用此功能, 因此, tk 参数并不是随机生成的, 而是与 asin 有关\n  使用编辑器, 全局搜索 tk , 发现 tk 参数, 都是由 N.a.s2Tkk(t) 方法生成\nstatic asins(e, t) { return ve(this, void 0, void 0, (function*() { const a = yield n.a.get(`${this.ASINS_URL}/${e.code}`, { params: { asins: t, tk: N.a.s2Tkk(t) } }); return new Promise(e =\u0026gt; e(this.parseList(a))) })) }  调用 s2Tkk(t), 其中 t 参数和 asins: t, 为同一个, 因此得知, t: 为我们需要查询的 asin\n  进入 s2Tkk 方法\nstatic s2Tkk(e, t, s, a) { let n = [], o = [e, t, s, a]; for (let e = 0; e \u0026lt; o.length; e++) if (o[e] \u0026amp;\u0026amp; null != o[e] \u0026amp;\u0026amp; o[e].toString().length \u0026gt; 0) { let t = n.length; for (let t = 0; o[e] instanceof Array \u0026amp;\u0026amp; t \u0026lt; o[e].length; t++) n.push(o[e][t]); t === n.length \u0026amp;\u0026amp; n.push(o[e].toString()) } return n.length \u0026lt; 1 ? \u0026quot;\u0026quot; : this._cal(n.join(\u0026quot;\u0026quot;), this.EXT_VERSION) }  重点在于 this._cal() 方法与 this.EXT_VERSION参数\n  Ctrl + F 查找 this._cal() 方法, 得到了参数计算方法（这里不能据此将它视为安全的加密或身份认证）\nstatic _cal(e, t) { function s(e, t) { for (var s = 0; s \u0026lt; t.length - 2; s += 3) { var a = t.charAt(s + 2); a = \u0026quot;a\u0026quot; \u0026lt;= a ? a.charCodeAt(0) - 87 : Number(a), a = \u0026quot;+\u0026quot; == t.charAt(s + 1) ? e \u0026gt;\u0026gt;\u0026gt; a : e \u0026lt;\u0026lt; a, e = \u0026quot;+\u0026quot; == t.charAt(s) ? e + a \u0026amp; 4294967295 : e ^ a } return e } return function(e, t) { var a = t.split(\u0026quot;.\u0026quot;); t = Number(a[0]) || 0; for (var n = [], o = 0, i = 0; i \u0026lt; e.length; i++) { var r = e.charCodeAt(i); 128 \u0026gt; r ? n[o++] = r : (2048 \u0026gt; r ? n[o++] = r \u0026gt;\u0026gt; 6 | 192 : (55296 == (64512 \u0026amp; r) \u0026amp;\u0026amp; i + 1 \u0026lt; e.length \u0026amp;\u0026amp; 56320 == (64512 \u0026amp; e.charCodeAt(i + 1)) ? (r = 65536 + ((1023 \u0026amp; r) \u0026lt;\u0026lt; 10) + (1023 \u0026amp; e.charCodeAt(++i)), n[o++] = r \u0026gt;\u0026gt; 18 | 240, n[o++] = r \u0026gt;\u0026gt; 12 \u0026amp; 63 | 128) : n[o++] = r \u0026gt;\u0026gt; 12 | 224, n[o++] = r \u0026gt;\u0026gt; 6 \u0026amp; 63 | 128), n[o++] = 63 \u0026amp; r | 128) } for (e = t, o = 0; o \u0026lt; n.length; o++) e = s(e += n[o], \u0026quot;+-a^+6\u0026quot;); return e = s(e, \u0026quot;+-3^+b+-f\u0026quot;), 0 \u0026gt; (e ^= Number(a[1]) || 0) \u0026amp;\u0026amp; (e = 2147483648 + (2147483647 \u0026amp; e)), (a = e % 1e6).toString() + \u0026quot;.\u0026quot; + (a ^ t) }(e, t) }  根据 this._cal(n.join(\u0026quot;\u0026quot;), this.EXT_VERSION) 的调用位置，可以明确 _cal(e, t) 的两个参数：\ne: \u0026quot;B00DQFGJR4\u0026quot; # s2Tkk 汇总后的 ASIN 字符串 t: \u0026quot;300104.1364508470\u0026quot; # 下文 3.1.4 样本派生的 EXT_VERSION  原先调用 s2Tkk('', 'B00DQFGJR4') 时的空值会被过滤，不能把那里的第一个空参数误认为 _cal 的输入。\n  同理可查找到, this.EXT_VERSION 参数\nstatic init() { this.EXT_VERSION = a.a.version().replace(/\\./, \u0026quot;00\u0026quot;).replace(/\\./g, \u0026quot;0\u0026quot;) + \u0026quot;.1364508470\u0026quot; }  其中 a.a.version() 在当时样本中为扩展版本号 3.1.4，经这里的替换得到 300104.1364508470。这是历史样本常量；新版实现需要重新分析，不能保证只改版本号就能适配。\n  将上面的 js 代码整理一下, 如下\nfunction extVersion() { // 就是插件的版本, 替换了 . 再拼接了一个字符串而成 // 固定 2022 年样本，不代表当前扩展实现 const chrome_ext_version = '3.1.4' //300104.1364508470 return chrome_ext_version.replace(/\\./, \u0026quot;00\u0026quot;).replace(/\\./g, \u0026quot;0\u0026quot;) + \u0026quot;.1364508470\u0026quot; } function s2Tkk(e, t, s, a) { let n = [], o = [e, t, s, a]; for (let e = 0; e \u0026lt; o.length; e++) if (o[e] \u0026amp;\u0026amp; null != o[e] \u0026amp;\u0026amp; o[e].toString().length \u0026gt; 0) { let t = n.length; for (let t = 0; o[e] instanceof Array \u0026amp;\u0026amp; t \u0026lt; o[e].length; t++) n.push(o[e][t]); t === n.length \u0026amp;\u0026amp; n.push(o[e].toString()) } return n.length \u0026lt; 1 ? \u0026quot;\u0026quot; : _cal(n.join(\u0026quot;\u0026quot;), extVersion()) } function _cal(e, t) { function s(e, t) { for (var s = 0; s \u0026lt; t.length - 2; s += 3) { var a = t.charAt(s + 2); a = \u0026quot;a\u0026quot; \u0026lt;= a ? a.charCodeAt(0) - 87 : Number(a), a = \u0026quot;+\u0026quot; == t.charAt(s + 1) ? e \u0026gt;\u0026gt;\u0026gt; a : e \u0026lt;\u0026lt; a, e = \u0026quot;+\u0026quot; == t.charAt(s) ? e + a \u0026amp; 4294967295 : e ^ a } return e } return function (e, t) { var a = t.split(\u0026quot;.\u0026quot;); t = Number(a[0]) || 0; for (var n = [], o = 0, i = 0; i \u0026lt; e.length; i++) { var r = e.charCodeAt(i); 128 \u0026gt; r ? n[o++] = r : (2048 \u0026gt; r ? n[o++] = r \u0026gt;\u0026gt; 6 | 192 : (55296 == (64512 \u0026amp; r) \u0026amp;\u0026amp; i + 1 \u0026lt; e.length \u0026amp;\u0026amp; 56320 == (64512 \u0026amp; e.charCodeAt(i + 1)) ? (r = 65536 + ((1023 \u0026amp; r) \u0026lt;\u0026lt; 10) + (1023 \u0026amp; e.charCodeAt(++i)), n[o++] = r \u0026gt;\u0026gt; 18 | 240, n[o++] = r \u0026gt;\u0026gt; 12 \u0026amp; 63 | 128) : n[o++] = r \u0026gt;\u0026gt; 12 | 224, n[o++] = r \u0026gt;\u0026gt; 6 \u0026amp; 63 | 128), n[o++] = 63 \u0026amp; r | 128) } for (e = t, o = 0; o \u0026lt; n.length; o++) e = s(e += n[o], \u0026quot;+-a^+6\u0026quot;); return e = s(e, \u0026quot;+-3^+b+-f\u0026quot;), 0 \u0026gt; (e ^= Number(a[1]) || 0) \u0026amp;\u0026amp; (e = 2147483648 + (2147483647 \u0026amp; e)), (a = e % 1e6).toString() + \u0026quot;.\u0026quot; + (a ^ t) }(e, t) }    使用 Python 进行离线调用\n本次在 Python 3.12.14、Node.js 24.21.0、PyExecJS 1.5.1 下验证。先确保 node --version 可运行，再在隔离环境执行 python -m pip install \u0026quot;PyExecJS==1.5.1\u0026quot;。这里保留原文的调用方式；PyExecJS 已停止维护，不应将其作为持续维护的依赖推荐。\n将第 6 步保存为 sellersprite.js，下面保存为同目录下的 verify_sellersprite.py，运行 python verify_sellersprite.py。它只在本机执行 JavaScript，不联网。\nfrom pathlib import Path import execjs node = execjs.get('Node') file = Path(__file__).with_name('sellersprite.js') ctx = node.compile(file.read_text(encoding='utf-8')) asin = 'B00DQFGJR4' token = ctx.call('s2Tkk', asin) assert ctx.call('extVersion') == '300104.1364508470' assert ctx.call('s2Tkk', '', asin) == token assert ctx.call('s2Tkk') == '' assert token == '58497.291017' print(token) # 固定 3.1.4 样本的离线计算值  这个结果复现了文中样本的参数计算，没有验证真实服务是否接受该值。扩展权限、登录凭据、网络接口和新版算法均不在本次验证范围。\n  当时对插件登录参数也采用了类似的定位方法，下图仅保留为历史分析记录；这里未提供或验证可运行的登录流程。\n如需要帮助, 可以通过 Github 联系我\n      "},{id:11,href:"/blog/4217449500/",title:"[Go] 数组, 切片的长度与容量",description:"介绍 Go 数组与切片的声明和基本属性，比较固定大小、长度与容量、值传递，以及切片共享底层数组的行为，附数组和切片结构示意图。",content:"来源: Capacity and length of a slice in Go。下面补齐声明及共享底层数组的示例，语义以 Go 语言规范为准。\n适用环境：仅使用标准库，在 Go 1.23.3、Windows/amd64 验证。完整示例保存为 main.go 后运行 go run main.go。\n数组 数组是固定长度、元素类型相同的序列，声明形式为 var name [size]type。\n数组的属性  长度是数组类型的一部分，[4]int 和 [5]int 是不同类型，不能直接相互赋值或比较。 未显式初始化的元素为其类型的零值，例如 var a [4]int 的四个元素均为 0。 数组赋值或作为值参数传递会复制数组值。若元素本身是指针等引用性数据，这不是递归的深拷贝。 元素类型可比较时，相同类型的数组可用 == 比较；切片的比较规则不同。  切片 声明形式为 var name []type。\n切片的属性  len(s) 是当前切片的元素个数，cap(s) 是从起点到其底层数组末端可容纳的元素个数。 var s []int 声明一个 nil 切片，长度与容量均为 0；[]int{} 是非 nil 的空切片，长度与容量也可以为 0。切片只能直接与 nil 比较，不能使用 a == b 比较两个切片。 切片赋值会复制切片值，两份切片最初共享底层数组；修改共享范围内的元素会互相可见。 append 返回新的切片值，必须接收返回结果。容量足够时可能继续使用原数组；容量不足时分配新数组，后续修改不再影响原数组。具体扩容倍数是实现细节。  package main import \u0026quot;fmt\u0026quot; func main() { a := [3]int{1, 2, 3} b := a b[0] = 9 fmt.Println(a, b) // [1 2 3] [9 2 3] s := make([]int, 2, 3) s[0], s[1] = 1, 2 shared := s shared[0] = 9 fmt.Println(s) // [9 2] grown := append(s, 3) // 原容量为 3，仍能使用同一底层数组。 grown[1] = 8 fmt.Println(s, grown) // [9 8] [9 8 3] detached := append(grown, 4) // 长度超过原容量，分配新的底层数组。 detached[0] = 7 fmt.Println(grown, detached) // [9 8 3] [7 8 3 4] var nilSlice []int emptySlice := []int{} fmt.Println(len(nilSlice), cap(nilSlice), nilSlice == nil) // 0 0 true fmt.Println(len(emptySlice), cap(emptySlice), emptySlice == nil) // 0 0 false }  输出应与注释一致。不要根据某一次扩容后的容量推导固定扩容算法；这里仅用“超过原容量”保证示例中最后一次 append 必须分配新数组。\n"},{id:12,href:"/blog/3160062725/",title:"[Go] 中的陷阱",description:"整理 Go 中容易混淆的行为，比较 UTF-8 字节长度与 rune 数量、nil 的使用、浮点数计算，以及 string 转换和 strconv.Itoa 的区别。",content:"适用环境：每个完整代码块分别保存为 main.go，在 Go 1.23.3、Windows/amd64 验证。标为编译错误的 nil 示例故意展示非法赋值；其余示例可使用 go run main.go。浮点打印结果用于观察当前示例，不能作为十进制数精确运算的保证。\n  字符串的长度与数量\n// Number of Bytes package main import \u0026quot;fmt\u0026quot; func main() { data := \u0026quot;We♥Go\u0026quot; fmt.Println(len(data)) } // 7 // string 是只读字节序列，不保证任意内容都是有效 UTF-8。 // 本例文字是有效 UTF-8，其中 ♥ 占 3 字节，因此总长度为 7。  // Number of Runes package main import ( \u0026quot;fmt\u0026quot; \u0026quot;unicode/utf8\u0026quot; ) func main() { data := \u0026quot;We♥Go\u0026quot; fmt.Println(utf8.RuneCountInString(data)) } // 5 // RuneCountInString 统计 Unicode 码点数量，不是用户眼中的字形数量；组合字符和 emoji 可能包含多个码点。    用 nil 初始化变量\npackage main import \u0026quot;fmt\u0026quot; func main() { var data string = nil if data == nil { fmt.Println(data) } } // cannot use nil as type string in assignment  nil 是预定义标识符，可以赋给指针、切片、map、channel、函数和接口等支持 nil 的类型；string 不属于这些类型，它的零值是 \u0026quot;\u0026quot;。上面的程序是预期编译失败示例，赋值和比较都不合法。\npackage main import \u0026quot;fmt\u0026quot; func main() { var data *string = nil if data == nil { fmt.Println(data) } } // \u0026lt;nil\u0026gt; // *string 是指向字符串类型值的指针变量的类型。指针的零值是 nil。    浮点数乘法\npackage main import \u0026quot;fmt\u0026quot; func main() { var m = 1.39 fmt.Println(m * m) const n = 1.39 fmt.Println(n * n) } // 1.9320999999999997 // 1.9321    字符串类型转换\npackage main import \u0026quot;fmt\u0026quot; func main() { i := 105 s := string(i) fmt.Println(s) } // i // 字符串支持从 int 类型转换，这里 string() 将整数视为字符。 105的字符是 i。    整数转字符串\npackage main import ( \u0026quot;fmt\u0026quot; \u0026quot;strconv\u0026quot; ) func main() { i := 105 s := strconv.Itoa(i) fmt.Println(s) s = fmt.Sprintf(\u0026quot;%d\u0026quot;, i) fmt.Println(s) } // 请使用 strconv.Itoa() 或 fmt.Sprintf() 函数。    验证：前两个字符串程序分别输出 7 与 5；合法 nil 指针程序输出 \u0026lt;nil\u0026gt;；string(105) 输出 i，整数格式化两次输出 105。go vet 可能专门提示整数到字符串的码点转换，这是该反例要区分的行为。参考 Go 规范：字符串、转换与 utf8.RuneCountInString。\n"},{id:13,href:"/blog/1213148850/",title:"A Bits of Unsolicited Advice",description:"A bilingual collection of life advice on learning, listening, habits, creativity, gratitude and taking responsibility, with English quotations and Chinese notes.",content:"A Bits of Unsolicited Advice   Being enthusiastic is worth 25 IQ points.\n学习如何从那些你不同意, 甚至冒犯你的人身上学习. 看看你是否能从他们的观点中找到真理\n  Being enthusiastic is worth 25 IQ points.\n热情是值得25个IQ点的\n  Always demand a deadline. A deadline weeds out the extraneous and the ordinary. It prevents you from trying to make it perfect, so you have to make it different. Different is better.\n总是要求有一个最后期限, 一个最后期限可以剔除不相干和普通的东西. 它阻止你试图让它变得完美，所以你必须让它变得不同. 不同就是更好.\n  Don’t be afraid to ask a question that may sound stupid because 99% of the time everyone else is thinking of the same question and is too embarrassed to ask it.\n不要害怕问一个听起来可能很愚蠢的问题, 因为 99% 的时候其他人都在想相同的问题, 但是却不好意思问\n  Being able to listen well is a superpower. While listening to someone you love keep asking them “Is there more?”, until there is no more.\n善于倾听是一种超能力. 在倾听你所爱的人时, 不断的询问 \u0026ldquo;还有吗?\u0026rdquo; 直到没有.\n  A worthy goal for a year is to learn enough about a subject so that you can’t believe how ignorant you were a year earlier.\n一年中有一个价值的目标是学习足够的知识, 这会使你无法相信一年前的你是多么的无知.\n  Gratitude will unlock all other virtues and is something you can get better at.\n感恩会解锁其他美德, 这会使你变得更好\n  Treating a person to a meal never fails, and is so easy to do. It’s powerful with old friends and a great way to make new friends.\n请人吃饭永远不会失败, 而且很容易做到. 这对老朋友来说很有帮助. 也是结交新朋友的好方法\n  Reading to your children regularly will bond you together and kick-start their imaginations.\n定期与孩子一起读书会把你们联系在一起, 激发他们的想象力\n  Extraordinary claims should require extraordinary evidence to be believed.\n非凡的主张需要非凡的证据才能被相信\n  Don’t be the smartest person in the room. Hangout with, and learn from, people smarter than yourself. Even better, find smart people who will disagree with you.\n不要成为房间里最聪明的人. 与比自己更聪明的人交流并向他们学习. 甚至更好的是, 找到那些与你意见相左的人\n  Rule of 3 in conversation. To get to the real reason, ask a person to go deeper than what they just said. Then again, and once more. The third time’s answer is close to the truth.\n谈话中的 3 条规则. 要想知道真正的原因, 请一个人比他们刚才说的更加深入, 然后一而再, 再而三. 就接近真相了.\n  Don’t be the best. Be the only.\n不要做最好的, 要做唯一的\n  Promptness is a sign of respect.\n及时是尊重的表现\n  The purpose of a habit is to remove that action from self-negotiation. You no longer expend energy deciding whether to do it. You just do it. Good habits can range from telling the truth, to flossing.\n养成习惯的目的是从自我协商中消除这种行为. 你不在花费精力来决定是否做这件事情. 你只是做了它. 好的习惯可以从诚实到使用牙线\n  Optimize your generosity. No one on their deathbed has ever regretted giving too much away.\n不要吝啬你的慷慨, 没有人会在临终前觉得自己付出太多\n  To make something good, just do it. To make something great, just re-do it, re-do it, re-do it. The secret to making fine things is in remaking them.\n要做好事, 就去做. 要想做出伟大的东西, 只要重做, 重做, 重做. 创造美好的事物的秘诀在于不断重试\n  To make mistakes is human. To own your mistakes is divine. Nothing elevates a person higher than quickly admitting and taking personal responsibility for the mistakes you make and then fixing them fairly. If you mess up, fess up. It’s astounding how powerful this ownership is.\n犯错误是人之常情. 拥有自己的错误是神圣的. 没有什么比迅速承认并且为你所犯的错误承担责任. 然后公平的纠正它们更能提升一个人的地位. 如果你搞砸了, 坦白承认吧, 这种所有权的力量是令人震惊的.\n  Separate the processes of creation from improving. You can’t write and edit, or sculpt and polish, or make and analyze at the same time. If you do, the editor stops the creator. While you invent, don’t select. While you sketch, don’t inspect. While you write the first draft, don’t reflect. At the start, the creator mind must be unleashed from judgment.\n将创作和改进的过程分开. 你不能同时进行写作和编辑, 雕刻或抛光, 制作与分析. 如果你这样做, 编辑会妨碍你的创作. 当你发明时, 不要选择. 当你画草图时, 不要检查. 当你写第一稿时, 不要反思. 在开始时, 创作者的头脑必须从判断中解放出来.\n  If you are not falling down occasionally, you are just coasting.\n如果你没有偶尔摔倒, 你就是在滑行\n  Perhaps the most counter-intuitive truth of the universe is that the more you give to others, the more you’ll get. Understanding this is the beginning of wisdom.\n也许宇宙中最反直觉的真理是, 你给别人的越多, 你得到的就越多. 明摆这一点是智慧的开始\n  Be prepared: When you are 90% done any large project (a house, a film, an event, an app) the rest of the myriad details will take a second 90% to complete.\n做好准备. 当你完成任何大型项目(房子, 电影, 活动, 应用程序) 的 90% 的时候, 剩余无数的细节将需要第二个 90% 来完成\n  Anything real begins with the fiction of what could be. Imagination is therefore the most potent force in the universe, and a skill you can get better at. It’s the one skill in life that benefits from ignoring what everyone else knows.\n任何真实的东西都始于对可能事情的虚构. 因此, 想象力是宇宙中最强大的力量, 也是一种你可以变得更好的技能. 它是生活中一种技能, 可以从其他人忽略的事情中收益\n  When crisis and disaster strike, don’t waste them. No problems, no progress.\n当危机和灾难来临时, 不要浪费它们. 没有问题, 就没有进步\n  Eliminating clutter makes room for your true treasures.\n消除杂乱无章的东西, 为你真正的宝藏提供空间.\n  A vacation + a disaster = an adventure.\n一个假期 + 一个灾难 = 一次冒险\n  Following your bliss is a recipe for paralysis if you don’t know what you are passionate about. A better motto for most youth is “master something, anything”. Through mastery of one thing, you can drift towards extensions of that mastery that bring you more joy, and eventually discover where your bliss is.\n如果你不知道自己对什么有热情, 跟着自己兴趣走是一种好的方法. 对大多数年轻人来说, 一个好的座右铭是 \u0026ldquo;掌握一些东西, 任何东西\u0026rdquo;, 通过对一件事的掌握，你可以朝着能给你带来更多快乐的掌握的延伸方向发展，并最终发现你的幸福在哪里。\n  "},{id:14,href:"/blog/1624364114/",title:"[Go] Goroutines 和 Channels 练习",description:"收集六个 Go 并发练习，涵盖奇偶分流、多协程写入通道、生成器、斐波那契数列、执行顺序和 WaitGroup 检查点同步。",content:"适用环境：各个 package main 代码块是独立程序，分别保存为 main.go，在 Go 1.23.3、Windows/amd64 运行 go run main.go 验证。所有示例均有结束条件；除明确给出的数值集合外，不保证 goroutine 间的输出顺序。\n  查找奇数和偶数\n/* 查找奇数和偶数 下面的程序启动了两个 Goroutine。这两个 Goroutine 现在并发运行。我们创建了两个无缓冲通道，并将它们作为参数传递给 goroutines，其中包含通道接收到的值。 */ package main import \u0026quot;sync\u0026quot; func main() { nums := []int{1, 2, 3, 4, 5, 6, 7, 8, 9, 0} chOdd := make(chan int) chEven := make(chan int) var wg sync.WaitGroup wg.Add(2) go func() { defer wg.Done() odd(chOdd) }() go func() { defer wg.Done() even(chEven) }() for _, v := range nums { if v%2 == 0 { chEven \u0026lt;- v } else { chOdd \u0026lt;- v } } close(chOdd) close(chEven) wg.Wait() } func even(ch chan int) { for v := range ch { println(\u0026quot;偶数: \u0026quot;, v) } } func odd(ch chan int) { for v := range ch { println(\u0026quot;奇数: \u0026quot;, v) } }    启动多个 Goroutines，每个 Goroutine 将值添加到 Channel\n/* 启动多个 Goroutines，每个 Goroutine 将值添加到 Channel 该程序以 10 个 Goroutines 开始。我们创建了一个ch字符串通道，并通过同时运行 10 个 goroutine 将数据写入该通道。箭头相对于通道的方向指定是发送还是接收数据。指向ch的箭头指定我们正在写入通道ch。从ch向外指向的箭头指定我们正在从通道ch读取。 */ package main import ( \u0026quot;fmt\u0026quot; \u0026quot;strconv\u0026quot; ) func main() { ch := make(chan string) for i := 0; i \u0026lt; 10; i++ { go func(i int) { for j := 0; j \u0026lt; 10; j++ { ch \u0026lt;- \u0026quot;Goroutine: \u0026quot; + strconv.Itoa(i) } }(i) } for k := 1; k \u0026lt;= 100; k++ { fmt.Println(k, \u0026lt;-ch) } }    从通道发送和接收值\n/* 从通道发送和接收值 主要功能有生成器和接收器两个函数。我们创建一个c int 通道并从生成器函数返回它。在匿名 goroutine 中运行的 for 循环将值写入通道c。 */ package main import \u0026quot;fmt\u0026quot; func main() { c := generator() receiver(c) } func receiver(c \u0026lt;-chan int) { for v := range c { fmt.Println(v) } } func generator() \u0026lt;-chan int { ch := make(chan int) go func() { for i := 0; i \u0026lt; 10; i++ { ch \u0026lt;- i } close(ch) }() return ch }    读取斐波那契数列并将其写入通道\n/* 读取斐波那契数列并将其写入通道 main 函数有两个无缓冲通道ch和quit。在 fibonacci 函数内部，select语句会阻塞，直到它的一种情况准备就绪。 */ package main import \u0026quot;fmt\u0026quot; func main() { ch := make(chan int) quit := make(chan bool) n := 10 go func(n int) { for i := 0; i \u0026lt; n; i++ { fmt.Println(\u0026lt;-ch) } quit \u0026lt;- false }(n) fibonacci(ch, quit) } func fibonacci(ch chan int, quit chan bool) { x, y := 0, 1 for { select { case ch \u0026lt;- x: x, y = y, x+y case \u0026lt;-quit: fmt.Println(\u0026quot;quit\u0026quot;) return } } }    Goroutines 通道执行顺序\n/* Goroutines 通道执行顺序 本例创建四个 goroutine，使用无缓冲通道返回四组求和结果。收到的顺序由调度决定，即使只有两个 goroutine 也不保证固定顺序。结果集合是 80、268、112、296；接收完成后由接收方关闭通道在这里是安全的，因为发送次数已知且全部完成。 */ package main import \u0026quot;fmt\u0026quot; func sum(a []int, c chan int) { sum := 0 for _, v := range a { sum += v } c \u0026lt;- sum } func main() { a := []int{17, 12, 18, 9, 24, 42, 64, 12, 68, 82, 57, 32, 9, 2, 12, 82, 52, 34, 92, 36} c := make(chan int) for i := 0; i \u0026lt; len(a); i = i + 5 { go sum(a[i:i+5], c) } output := make([]int, 4) for i := 0; i \u0026lt; 4; i++ { output[i] = \u0026lt;-c } close(c) fmt.Println(output) }    检查点同步图\n/* 检查点同步图示 检查点同步是一个多任务同步的问题。考虑一个车间，其中有几个工人组装某些机构的细节。当他们每个人完成他的工作时，他们会把细节放在一起。没有商店，所以第一个完成它的部分的工人必须等待其他人才能开始另一个。将细节放在一起是任务在分开路径之前同步自己的检查点。 */ package main import ( \u0026quot;log\u0026quot; \u0026quot;math/rand\u0026quot; \u0026quot;sync\u0026quot; \u0026quot;time\u0026quot; ) var ( partList = []string{\u0026quot;A\u0026quot;, \u0026quot;B\u0026quot;, \u0026quot;C\u0026quot;, \u0026quot;D\u0026quot;} nAssemblies = 3 wg sync.WaitGroup ) func main() { rand.Seed(time.Now().UnixNano()) for c := 1; c \u0026lt;= nAssemblies; c++ { log.Println(\u0026quot;begin assembly cycle\u0026quot;, c) wg.Add(len(partList)) for _, part := range partList { go worker(part) } wg.Wait() log.Println(\u0026quot;assemble. cycle\u0026quot;, c, \u0026quot;complete\u0026quot;) } } func worker(part string) { log.Println(part, \u0026quot;worker begin part\u0026quot;) time.Sleep(time.Duration(rand.Int63n(1e6))) log.Println(part, \u0026quot;worker completes part\u0026quot;) wg.Done() }    来源: https://www.golangprograms.com/goroutines-and-channels-example.html 验证要点：第 1 个程序应完整输出 10 个数后退出，关闭通道结束 range，WaitGroup 等待消费者结束；第 2、3、4 个程序分别接收 100、10、10 个值；第 5 个程序仅输出四个和而不附带多余的零；第 6 个程序的每轮 complete 必须位于该轮四个 worker 完成之后。WaitGroup.Add 在启动对应 goroutine 前调用。参考 Go 官方 WaitGroup 文档和通道语义。\n"},{id:15,href:"/blog/218469985/",title:"[Go] defer 理解",description:"结合三个命名返回值示例，梳理 Go defer 的后进先出执行顺序，以及闭包引用、参数传值和 return 赋值对最终返回结果的影响。",content:"什么是 defer defer 是 Go 语言提供的延迟调用机制：执行到 defer 语句时会求值并保存被调用函数及其参数，函数调用推迟到当前函数退出时执行。\n多个延迟调用按后进先出（LIFO）的顺序执行；正常返回时，在返回结果赋值之后、函数真正返回调用方之前运行。这里的“栈”是理解执行顺序的比喻，不要求运行时一定采用某种栈布局。\n先进后出的原因是后面定义的函数可能会依赖前面的资源，自然要先执行；否则，如果前面先执行，那后面函数的依赖就没有了。\n踩坑点 使用 defer 最容易采坑的地方是和带命名返回参数的函数一起使用时。\ndefer 语句定义时, 对外部变量的引用有两种方式\n 函数参数: 在 defer 定义时就把值传递给 defer, 并缓存起来 闭包引用: 在 defer 函数被取出调用时根据整个上下文确定当前值  理解 return 语句 理解普通返回时，可以用下面的教学伪代码表示“先给返回结果赋值、再执行延迟调用、最后返回调用方”的顺序。它不是 Go 源码或编译器的固定降级实现，不能单独编译：\nval = xxx return  而 defer 语句就是在这两条语句之间执行，也就是\nval = xxx deferFunc return  实践检验 适用环境：下面的完整程序在 Go 1.23.3、Windows/amd64 验证。保存为 main.go，执行 go run main.go，依次输出 1、1、1。f3 的延迟调用参数在注册时取到的是初始值 0；形参自增不会改变命名返回值 r。注释中的“拆分”仅作结果赋值顺序示意。\npackage main import \u0026quot;fmt\u0026quot; func f1() (r int) { defer func() { r++ }() return 0 } // 拆分 f1 //func f1() (r int) { // // // 1.赋值 // r = 0 // // // 2.闭包引用，返回值被修改 // defer func() { // r++ // }() // // // 3.return // return //} func f2() (r int) { t := 1 defer func() { t++ }() return t } // 拆分 f2 //func f2() (r int) { // t := 1 // // 1.赋值 // r = t // // // 2.闭包引用，但是没有修改返回值 r // defer func() { // t++ // }() // // // 3.return // return //} func f3() (r int) { defer func(r int) { r++ }(r) return 1 } // 拆分 f3 //func f3() (r int) { // // // 1.执行到 defer 时先求值并保存实参，此时 r 为 0 // savedArg := r // // // 2.return 语句给命名返回值赋值 // r = 1 // // // 3.示意执行已注册的延迟调用，形参自增不影响返回值 r // func(r int) { // r++ // }(savedArg) // // // 4.返回调用方 // return //} func main() { fmt.Println(f1()) fmt.Println(f2()) fmt.Println(f3()) }  行为依据见 Go 语言规范：defer。闭包共享的是所捕获的变量，并不是注册时自动复制其值；不要将参数求值时机与闭包执行时机混为一谈。\n"},{id:16,href:"/blog/4229706688/",title:"[Go] Interface",description:"通过结构体与方法示例梳理 Go interface 的定义和赋值，介绍 fmt.Stringer、接口参数、类型判断与接口嵌入，理解接口如何承载不同类型的值。",content:"interface类型 本文使用普通方法接口，示例只依赖标准库。各个完整 package main 程序分别保存为 main.go 后执行 go run main.go；接口嵌入末尾的类型定义是局部片段，不能单独运行。已在 Go 1.23.3、Windows/amd64 验证。\ninterface 类型定义了一组方法，某个类型的方法集满足接口要求时就实现该接口。T 与 *T 的方法集不同：本节接收者使用指针，因此示例通过 *Student、*Employee 赋给接口，不能由可寻址值能直接调用方法推断该值类型满足接口。\npackage main import \u0026quot;fmt\u0026quot; type Human struct { name string age int phone string } type Student struct { Human school string loan float32 } type Employee struct { Human company string money float32 } func (h *Human) SayHi() { fmt.Printf(\u0026quot;Hi, I am %s you can call me on %s\\n\u0026quot;, h.name, h.phone) } func (h *Human) Sing(lyrics string) { fmt.Println(\u0026quot;La la, la la la, la la la la la...\u0026quot;, lyrics) } func (h *Human) Guzzle(beerStein string) { fmt.Println(\u0026quot;Guzzle Guzzle Guzzle...\u0026quot;, beerStein) } func (e *Employee) SayHi() { fmt.Printf(\u0026quot;Hi, I am %s, I work at %s. Call me on %s\\n\u0026quot;, e.name, e.company, e.phone) } func (s *Student) BorrowMoney(amount float32) { s.loan += amount } func (e *Employee) SpendSalary(amount float32) { e.money -= amount } type Men interface { SayHi() Sing(lyrics string) Guzzle(beerStein string) } type Tom interface { SayHi() Sing(song string) BorrowMoney(amount float32) } type Jerry interface { SayHi() Sing(song string) SpendSalary(amount float32) } func main() { var person Men = \u0026amp;Student{Human: Human{name: \u0026quot;Mike\u0026quot;, phone: \u0026quot;222-222-XXX\u0026quot;}} person.SayHi() person.Sing(\u0026quot;November rain\u0026quot;) person.Guzzle(\u0026quot;one glass\u0026quot;) }  interface值 package main import \u0026quot;fmt\u0026quot; type Human struct { name string age int phone string } type Student struct { Human school string loan float32 } type Employee struct { Human company string money float32 } func (h Human) SayHi() { fmt.Printf(\u0026quot;Hi, I am %s you can call me on %s\\n\u0026quot;, h.name, h.phone) } func (h Human) Sing(lyrics string) { fmt.Println(\u0026quot;La la, la la la, la la la la la...\u0026quot;, lyrics) } func (e Employee) SayHi() { fmt.Printf(\u0026quot;Hi, I am %s, I work at %s. Call me on %s\\n\u0026quot;, e.name, e.company, e.phone) } type Men interface { SayHi() Sing(lyrics string) } func main() { mike := Student{Human{\u0026quot;Mike\u0026quot;, 25, \u0026quot;222-222-XXX\u0026quot;}, \u0026quot;MIT\u0026quot;, 0.00} paul := Student{Human{\u0026quot;Paul\u0026quot;, 26, \u0026quot;111-222-XXX\u0026quot;}, \u0026quot;Harvard\u0026quot;, 100} sam := Employee{Human{\u0026quot;Sam\u0026quot;, 36, \u0026quot;444-222-XXX\u0026quot;}, \u0026quot;Golang Inc.\u0026quot;, 1000} tom := Employee{Human{\u0026quot;Tom\u0026quot;, 37, \u0026quot;222-444-XXX\u0026quot;}, \u0026quot;Things Ltd.\u0026quot;, 5000} var i Men i = mike fmt.Println(\u0026quot;This is Mike, a Student:\u0026quot;) i.SayHi() i.Sing(\u0026quot;November rain\u0026quot;) i = tom fmt.Println(\u0026quot;This is tom, an Employee\u0026quot;) i.SayHi() i.Sing(\u0026quot;born to be wild\u0026quot;) fmt.Println(\u0026quot;Let's use a slice of Men and see what happens\u0026quot;) x := make([]Men, 3) x[0], x[1], x[2] = paul, sam, mike for _, value := range x { value.SayHi() } }  interface函数参数 package main import ( \u0026quot;fmt\u0026quot; \u0026quot;strconv\u0026quot; ) type Human struct { name string age int phone string } // 通过这个方法 Human 实现了 fmt.Stringer func (h Human) String() string { return \u0026quot;❰\u0026quot; + h.name + \u0026quot; - \u0026quot; + strconv.Itoa(h.age) + \u0026quot; years - ✆ \u0026quot; + h.phone + \u0026quot;❱\u0026quot; } func main() { Bob := Human{\u0026quot;Bob\u0026quot;, 39, \u0026quot;000-7777-XXX\u0026quot;} fmt.Println(\u0026quot;This Human is : \u0026quot;, Bob) }  interface变量存储的类型 package main import ( \u0026quot;fmt\u0026quot; \u0026quot;strconv\u0026quot; ) type Element interface{} type List [] Element type Person struct { name string age int } func (p Person) String() string { return \u0026quot;(name: \u0026quot; + p.name + \u0026quot; - age: \u0026quot;+strconv.Itoa(p.age)+ \u0026quot; years)\u0026quot; } func main() { list := make(List, 3) list[0] = 1 list[1] = \u0026quot;Hello\u0026quot; list[2] = Person{\u0026quot;Dennis\u0026quot;, 70} for index, element := range list{ switch value := element.(type) { case int: fmt.Printf(\u0026quot;list[%d] is an int and its value is %d\\n\u0026quot;, index, value) case string: fmt.Printf(\u0026quot;list[%d] is a string and its value is %s\\n\u0026quot;, index, value) case Person: fmt.Printf(\u0026quot;list[%d] is a Person and its value is %s\\n\u0026quot;, index, value) default: fmt.Printf(\u0026quot;list[%d] is of a different type\\n\u0026quot;, index) } } }  嵌入interface 我们可以看到源码包container/heap里面有这样的一个定义\ntype Interface interface { sort.Interface // 嵌入接口的方法集 Push(x interface{}) //a Push method to push elements into the heap Pop() interface{} //a Pop elements that pops elements from the heap }  嵌入 sort.Interface 会包含它的方法集，不是结构体中的嵌入字段；调用者仍需实现 Len、Less、Swap 三个方法：\ntype Interface interface { // Len is the number of elements in the collection. Len() int // Less returns whether the element with index i should sort // before the element with index j. Less(i, j int) bool // Swap swaps the elements with indexes i and j. Swap(i, j int) }  另一个例子就是io包下面的 io.ReadWriter ，它包含了io包下面的Reader和Writer两个interface：\n// io.ReadWriter type ReadWriter interface { Reader Writer }  验证：四个完整程序分别应输出问候语、不同具体类型的方法调用、Human.String() 格式化结果和列表的类型判断结果；可另运行 go vet main.go 检查格式化参数。方法集和接口嵌入规则见 Go 语言规范。\n"},{id:17,href:"/blog/1110384130/",title:"[Go] Method",description:"用 Human、Student 和 Employee 示例说明 Go 结构体嵌入带来的方法提升，以及外层类型定义同名 SayHi 方法后，方法调用行为如何变化。",content:"适用环境：两个完整程序分别保存为 main.go，在 Go 1.23.3、Windows/amd64 运行 go run main.go。Go 的结构体嵌入提供方法提升（promotion），并非面向对象语言中的类继承。\n嵌入与方法提升 package main import \u0026quot;fmt\u0026quot; type Human struct { name string age int phone string } type Student struct { Human school string } type Employee struct { Human company string } func (h *Human) SayHi() { fmt.Printf(\u0026quot;Hi, I am %s you can call me on %s\\n\u0026quot;, h.name, h.phone) } func main() { mark := Student{Human{\u0026quot;Mark\u0026quot;, 25, \u0026quot;222-222-YYYY\u0026quot;}, \u0026quot;MIT\u0026quot;} sam := Employee{Human{\u0026quot;Sam\u0026quot;, 45, \u0026quot;111-888-XXXX\u0026quot;}, \u0026quot;Golang Inc\u0026quot;} mark.SayHi() sam.SayHi() }  第一个程序中，mark.SayHi() 和 sam.SayHi() 使用从嵌入字段提升的方法；变量可寻址，调用时可自动取地址匹配 *Human 接收者。\n外层类型的同名方法 package main import \u0026quot;fmt\u0026quot; type Human struct { name string age int phone string } type Student struct { Human school string } type Employee struct { Human company string } func (h *Human) SayHi() { fmt.Printf(\u0026quot;Hi, I am %s you can call me on %s\\n\u0026quot;, h.name, h.phone) } // Employee 的同名方法会遮蔽通过嵌入字段提升的 SayHi。 func (e *Employee) SayHi() { fmt.Printf(\u0026quot;Hi, I am %s, I work at %s. Call me on %s\\n\u0026quot;, e.name, e.company, e.phone) //Yes you can split into 2 lines here. } func main() { mark := Student{Human{\u0026quot;Mark\u0026quot;, 25, \u0026quot;222-222-YYYY\u0026quot;}, \u0026quot;MIT\u0026quot;} sam := Employee{Human{\u0026quot;Sam\u0026quot;, 45, \u0026quot;111-888-XXXX\u0026quot;}, \u0026quot;Golang Inc\u0026quot;} mark.SayHi() sam.SayHi() }  第二个程序中，sam.SayHi() 调用 *Employee 的方法，而 sam.Human.SayHi() 仍可显式调用嵌入字段的方法。这里没有动态重写 Human 的行为；两次运行应分别看到通用问候和带公司名称的问候。参考 Go 语言规范：结构体嵌入及提升。\n"},{id:18,href:"/blog/3239669741/",title:"[Go] 字符串拼接性能",description:"对比 Go 中加号、fmt.Sprintf、strings.Builder、bytes.Buffer 与字节切片的拼接基准测试，讨论预分配容量和内存拷贝对性能的影响。",content:"1. 字符串高效拼接 适用环境：标准库基准示例在 Go 1.23.3、Windows/amd64 验证。将随机字符串、拼接函数、benchmark 和末尾的 builderGrowConcat 四个 Go 代码块合并保存为 concat_test.go。在空目录执行 go mod init example/concat，再运行 go test -run '^$' -bench . -benchmem -benchtime=1x -count=1 做一次有界检查；正式比较可增加运行次数并记录工具链及机器信息。\n1.1 为了避免编译器的优化， 首先实现一个生成长度为 n 的随机字符串的函数。 package concat import ( \u0026quot;bytes\u0026quot; \u0026quot;fmt\u0026quot; \u0026quot;math/rand\u0026quot; \u0026quot;strings\u0026quot; \u0026quot;testing\u0026quot; ) const letterBytes = \u0026quot;abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ\u0026quot; func randomString(n int) string { b := make([]byte, n) for i := range b { b[i] = letterBytes[rand.Intn(len(letterBytes))] } return string(b) }  常见的字符串拼接方式， 以下 5 种\n// + func plusConcat(n int, str string) string { s := \u0026quot;\u0026quot; for i := 0; i \u0026lt; n; i++ { s += str } return s } // fmt.Sprintf func sprintfConcat(n int, str string) string { s := \u0026quot;\u0026quot; for i := 0; i \u0026lt; n; i++ { s = fmt.Sprintf(\u0026quot;%s%s\u0026quot;, s, str) } return s } // strings.Builder func builderConcat(n int, str string) string { var builder strings.Builder for i := 0; i \u0026lt; n; i++ { builder.WriteString(str) } return builder.String() } // bytes.Buffer func bufferConcat(n int, str string) string { buf := new(bytes.Buffer) for i := 0; i \u0026lt; n; i++ { buf.WriteString(str) } return buf.String() } // []byte func byteConcat(n int, str string) string { buf := make([]byte, 0) for i := 0; i \u0026lt; n; i++ { buf = append(buf, str...) } return string(buf) } // 如果长度是可预知的，那么创建 []byte 时，我们还可以预分配切片的容量(cap)。 func preByteConcat(n int, str string) string { buf := make([]byte, 0, n*len(str)) for i := 0; i \u0026lt; n; i++ { buf = append(buf, str...) } return string(buf) }  1.2 benchmark 性能比拼 每个 benchmark 用例中，生成了一个长度为 10 的字符串，并拼接 1w 次。\nvar result string // 保留结果，避免只测到可被消除的无用计算。 func benchmark(b *testing.B, f func(int, string) string) { var str = randomString(10) b.ReportAllocs() b.ResetTimer() for i := 0; i \u0026lt; b.N; i++ { result = f(10000, str) } } func BenchmarkPlusConcat(b *testing.B) { benchmark(b, plusConcat) } func BenchmarkSprintfConcat(b *testing.B) { benchmark(b, sprintfConcat) } func BenchmarkBuilderConcat(b *testing.B) { benchmark(b, builderConcat) } func BenchmarkBufferConcat(b *testing.B) { benchmark(b, bufferConcat) } func BenchmarkByteConcat(b *testing.B) { benchmark(b, byteConcat) } func BenchmarkPreByteConcat(b *testing.B) { benchmark(b, preByteConcat) } func BenchmarkBuilderGrowConcat(b *testing.B) { benchmark(b, builderGrowConcat) }  历史测试结果（原记录未注明 Go 版本与内存统计，仅保留为该机器上的一次时间观测）：\ngoos: windows goarch: amd64 pkg: example/charpter-1 BenchmarkPlusConcat BenchmarkPlusConcat-6 18 56304633 ns/op BenchmarkSprintfConcat BenchmarkSprintfConcat-6 13 90110408 ns/op BenchmarkBuilderConcat BenchmarkBuilderConcat-6 12132 97072 ns/op BenchmarkBufferConcat BenchmarkBufferConcat-6 10000 104952 ns/op BenchmarkByteConcat BenchmarkByteConcat-6 10000 114187 ns/op BenchmarkPreByteConcat BenchmarkPreByteConcat-6 24522 48754 ns/op PASS  上述循环反复累积长字符串时，+ 和 fmt.Sprintf 的历史耗时较高；这不能推广成少量固定字符串相加一定慢。原输出没有 B/op、allocs/op，无法据此断言内存差多少倍；应使用 -benchmem 在相同输入及环境下比较。\n预分配 []byte 容量可以避免容量足够时的扩容与旧缓冲区搬迁，但每次 append 仍需把输入复制进缓冲区，最终 string(buf) 通常还要复制并分配字符串。它不是零拷贝方案，也不能保证在所有版本中都最快或内存最少。\n1.3 建议 综合易用性和性能，一般推荐使用 strings.Builder 来拼接字符串。\n这是 Go 官方对 strings.Builder 的解释：\n A Builder is used to efficiently build a string using Write methods. It minimizes memory copying.\n strings.Builder 也提供了预分配容量的方式 Grow，这里使用不同函数名，避免与前面的未预分配版本重复定义：\nfunc builderGrowConcat(n int, str string) string { var builder strings.Builder builder.Grow(n * len(str)) for i := 0; i \u0026lt; n; i++ { builder.WriteString(str) } return builder.String() }  Builder 可减少额外复制，但实际分配次数与字节数以基准输出为准，不保证恒定减半。Grow 的大小需非负且避免整数溢出；非零 Builder 不可复制使用。验证时所有函数应产生长度为 10000*10 的相同字符串，性能数字之外也要检查结果。参考 Go 官方 strings.Builder与 testing 基准文档。\n文章来源 极客兔兔-Go 语言高性能编程 "},{id:19,href:"/blog/1745614505/",title:"Python 面试题(1)",description:"通过示例讨论 Python 闭包的后期绑定和可变默认参数，展示默认参数绑定、functools.partial 及使用 None 作为默认值的处理思路。",content:"运行环境：以下示例在 CPython 3.12.14 验证，仅使用标准库。每个完整代码块可独立保存为 demo.py 并执行 python demo.py。第一题的重复结果和第二题的共享列表都是要观察的行为，不是语法错误。\n  闭包\ndef multipliers(): return [lambda x: i * x for i in range(4)] print([m(2) for m in multipliers()])  正确答案 [6, 6, 6, 6]\n错误答案 [0, 2, 4, 6]\n原因是闭包的后期绑定（late binding）：这些函数捕获的是同一个外层局部变量 i，并在调用时读取它。列表推导式结束后 i 为 3，所以之后对四个函数分别传入 2，都会得到 3 * 2 = 6。这也适用于用 def 定义的闭包，参见 Python 官方 FAQ。\n# 创建一个闭包，通过使用默认参数立即绑定它的参数 def multipliers(): return [lambda x, i=i: i * x for i in range(4)] print([m(2) for m in multipliers()]) # [0, 2, 4, 6]  或者使用 functools.partial 提前绑定乘法的第一个参数：\nfrom functools import partial from operator import mul def multipliers(): return [partial(mul, i) for i in range(4)] print([m(2) for m in multipliers()]) # [0, 2, 4, 6]    默认参数值是可变的\ndef extendList(val, list_val=[]): list_val.append(val) return list_val list1 = extendList(10) list2 = extendList(123, []) list3 = extendList('a') print(\u0026quot;list1 = %s\u0026quot; % list1) print(\u0026quot;list2 = %s\u0026quot; % list2) print(\u0026quot;list3 = %s\u0026quot; % list3) # 输出结果 # list1 = [10, 'a'] # list2 = [123] # list3 = [10, 'a']  默认参数表达式在函数定义时求值一次，而不是每次调用时重新求值。没有显式传入列表的 list1 和 list3 引用同一个默认列表；list2 使用显式传入的新列表。使用 None 作为默认值，再在函数体内创建列表，可以让省略列表参数的各次调用相互独立，参见官方函数定义说明。\n# 修改如下 def extendList(val, list_val=None): if list_val is None: list_val = [] list_val.append(val) return list_val list1 = extendList(10) list2 = extendList(123, []) list3 = extendList('a') print(\u0026quot;list1 = %s\u0026quot; % list1) print(\u0026quot;list2 = %s\u0026quot; % list2) print(\u0026quot;list3 = %s\u0026quot; % list3) # 输出结果 # list1 = [10] # list2 = [123] # list3 = ['a']    "},{id:20,href:"/blog/3380200713/",title:"Scrapy 永不停止的爬虫",description:"展示 Spider 空闲时追加请求、RedisSpider 按分钟等待新任务的示例，涉及 spider_idle 信号、DontCloseSpider 和等待超时后关闭的处理。",content:"本文讨论通过 spider_idle 信号保留爬虫、等待下一批任务的方法。下面将演示限制为有限次数，便于本地验证；长时间运行时仍应设置空闲超时、请求速率和外部停止机制。\n适用环境 本次示例在 Python 3.12.14、Scrapy 2.11.2、scrapy-redis 0.9.1 下验证，并固定 w3lib 2.2.1、Twisted 24.3.0，避免旧版 Scrapy 与新依赖的接口差异。Redis 队列测试另用 fakeredis 2.32.1，全部使用本地 data: 响应或模拟队列，不抓取外部网站。可在独立虚拟环境安装：\npython -m pip install \u0026quot;Scrapy==2.11.2\u0026quot; \u0026quot;scrapy-redis==0.9.1\u0026quot; \u0026quot;w3lib==2.2.1\u0026quot; \u0026quot;Twisted==24.3.0\u0026quot; \u0026quot;fakeredis==2.32.1\u0026quot;  Scrapy 的 spider_idle 信号不支持异步处理器，不能在其中使用 time.sleep(60) 阻塞事件循环。抛出 DontCloseSpider 后，处理器应立即返回；下一次空闲检查会再次触发该信号。通过 CloseSpider 可以提供关闭原因。\n在 Scrapy.Spider 中追加请求 保存为 idle_spider.py。这里使用内置的 data: 下载处理器生成本地响应，总共处理 3 次后正常结束。dont_filter=True 允许示例重复调度同一个 URL。\nfrom scrapy import Request, Spider, signals from scrapy.crawler import CrawlerProcess from scrapy.exceptions import DontCloseSpider class TestSpider(Spider): name = 'test' start_urls = ['data:text/plain,local-fixture'] max_requests = 3 def __init__(self, *args, **kwargs): super().__init__(*args, **kwargs) self.sent = 1 # start_urls 提供第一次请求 def parse(self, response, **kwargs): self.logger.info('local response: %s', response.text) def next_request(self): self.sent += 1 request = Request( self.start_urls[0], callback=self.parse, dont_filter=True, ) # Scrapy 2.6+ 不再传入 spider=self。 self.crawler.engine.crawl(request) def spider_idle(self): if self.sent \u0026gt;= self.max_requests: return # 不再抛出 DontCloseSpider，允许正常关闭 self.next_request() raise DontCloseSpider @classmethod def from_crawler(cls, crawler, *args, **kwargs): spider = super().from_crawler(crawler, *args, **kwargs) crawler.signals.connect(spider.spider_idle, signal=signals.spider_idle) return spider if __name__ == '__main__': process = CrawlerProcess({ 'LOG_LEVEL': 'INFO', 'TELNETCONSOLE_ENABLED': False, 'REQUEST_FINGERPRINTER_IMPLEMENTATION': '2.7', }) crawler = process.create_crawler(TestSpider) process.crawl(crawler) process.start() stats = crawler.stats.get_stats() assert stats['downloader/response_count'] == 3 assert stats['finish_reason'] == 'finished' print('local responses: 3; finish reason: finished')  运行 python idle_spider.py。最后的断言检查实际处理次数及关闭原因；日志中的响应来自本地固定文本，不能据此判断任何网站的抓取结果。\n在 RedisSpider 中等待新任务 RedisSpider.start_requests() 从 Redis 队列读取任务，不能依赖普通 Spider 的 start_urls 自动产生初始请求。在 scrapy-redis 0.9.1 中，应覆盖 make_request_from_data，使用队列里取出的数据生成请求，而不是忽略参数、始终请求 self.start_urls[0]。\n保存为 redis_wait_spider.py。示例约定队列元素为 {\u0026quot;url\u0026quot;: \u0026quot;data:text/plain,first\u0026quot;} 这样的 JSON 字符串。它只演示从 Redis 获取入口任务，使用 Scrapy 默认调度器；多进程共享调度队列、持久化与去重需另行配置。\nimport json import os from time import monotonic from scrapy import Request from scrapy.exceptions import CloseSpider, DontCloseSpider from scrapy_redis.spiders import RedisSpider class RedisWaitSpider(RedisSpider): name = 'redis_wait' redis_key = f'{name}:start_urls' poll_interval = 60 max_idle_seconds = 60 * 60 custom_settings = { 'REDIS_URL': os.environ.get('REDIS_URL', 'redis://127.0.0.1:6379/0'), } def __init__(self, *args, **kwargs): super().__init__(*args, **kwargs) self._clock = monotonic self._empty_since = None self._next_poll = 0.0 def make_request_from_data(self, data): payload = json.loads(data.decode(self.redis_encoding)) return Request(payload['url'], callback=self.parse, dont_filter=True) def parse(self, response, **kwargs): self.logger.info('processed queued URL: %s', response.url) def spider_idle(self): now = self._clock() if now \u0026gt;= self._next_poll: requests = list(self.next_requests()) for request in requests: self.crawler.engine.crawl(request) self._next_poll = now + self.poll_interval if requests: self._empty_since = None elif self._empty_since is None: self._empty_since = now if (self._empty_since is not None and now - self._empty_since \u0026gt;= self.max_idle_seconds): raise CloseSpider('redis_idle_timeout') raise DontCloseSpider  RedisSpider.from_crawler() 已连接此实例的 spider_idle，无需重复连接。未到下一次轮询时间时，处理器立即返回；达到轮询时间才读取队列。实际时机还取决于 Scrapy 的空闲检查，因此不是精确的每分钟定时器。这里的超时从首次观察到空队列开始计算，取到新任务后重置。若没有空闲超时，空队列可能使进程一直保留；time.sleep() 则会阻塞其他下载和回调。\n不启动 Redis 服务的有限验证 把下面代码保存为同目录下的 verify_redis_wait.py。它使用 fakeredis、模拟的引擎和可推进的时钟，不启动下载器，也不实际等待一小时。\nimport json from types import SimpleNamespace from unittest.mock import patch import fakeredis from scrapy.crawler import Crawler from scrapy.exceptions import CloseSpider, DontCloseSpider from scrapy.settings import Settings from redis_wait_spider import RedisWaitSpider server = fakeredis.FakeStrictRedis() crawler = Crawler(RedisWaitSpider, Settings()) scheduled = [] crawler.engine = SimpleNamespace(crawl=scheduled.append) with patch('scrapy_redis.connection.from_settings', return_value=server): spider = RedisWaitSpider.from_crawler(crawler) clock = [0.0] spider._clock = lambda: clock[0] server.rpush(spider.redis_key, json.dumps({'url': 'data:text/plain,initial'})) initial = list(spider.start_requests()) assert [request.url for request in initial] == ['data:text/plain,initial'] def expect_wait(): try: spider.spider_idle() except DontCloseSpider: return raise AssertionError('expected DontCloseSpider') server.rpush(spider.redis_key, json.dumps({'url': 'data:text/plain,first'})) expect_wait() assert [request.url for request in scheduled] == ['data:text/plain,first'] clock[0] = 1.0 server.rpush(spider.redis_key, json.dumps({'url': 'data:text/plain,second'})) expect_wait() assert server.llen(spider.redis_key) == 1 # 尚未达到下一轮询时间 clock[0] = 60.0 expect_wait() assert scheduled[-1].url == 'data:text/plain,second' assert len(scheduled) == 2 clock[0] = 120.0 expect_wait() # 首次观察到空队列 clock[0] = 180.0 server.rpush(spider.redis_key, json.dumps({'url': 'data:text/plain,third'})) expect_wait() assert scheduled[-1].url == 'data:text/plain,third' assert spider._empty_since is None # 新任务重置空闲超时 clock[0] = 240.0 expect_wait() # 再次从空队列开始计时 clock[0] = 3839.0 expect_wait() clock[0] = 3840.0 try: spider.spider_idle() except CloseSpider as exc: assert exc.reason == 'redis_idle_timeout' else: raise AssertionError('expected idle timeout') print('queue URLs, polling interval and idle timeout: OK')  运行 python verify_redis_wait.py，通过后输出 queue URLs, polling interval and idle timeout: OK。该检查覆盖初始任务、队列 URL 的使用、轮询间隔、新任务重置计时和超时分支；没有验证真实 Redis 连接、网络故障、分布式调度或外部网站抓取。实际运行前需根据目标服务与项目版本另行验证这些部分。\n"},{id:21,href:"/blog/612516780/",title:"单分派泛函数",description:"介绍 Python 单分派泛函数，通过 functools.singledispatch 的类型注册、registry 查询和不同类型的合并示例，展示按首个参数类型选择实现的方法。",content:"运行环境：下列两个完整代码块分别在 CPython 3.12.14 验证，仅需标准库；分别保存为 dispatch_basics.py、dispatch_add.py，执行 python 文件名.py 并对照输出注释。函数对象的内存地址会随运行变化，不作为输出一致性的判断依据。\nsingledispatch 是 PEP443 中引入的\n 单分派：根据一个参数的类型，以不同方式执行相同的操作的行为 多分派：可根据多个参数的类型选择专门的函数的行为 泛函数：多个函数绑在一起组合成一个泛函数  初步认识\nfunctools.singledispatch 按第一个参数的运行时类型选择实现；没有精确注册时会按继承关系查找，最后回退到最初的 object 实现。register 返回注册前的函数，所以 fun_num is fun 为 False。\nfrom decimal import Decimal from functools import singledispatch @singledispatch def fun(arg): print(arg) @fun.register(str) def _(arg): print(type(arg), arg) @fun.register(int) def _(arg): print(type(arg), arg) @fun.register(list) def _(arg): print(type(arg), arg) @fun.register(type(None)) def _(arg): print(type(arg), arg) @fun.register(float) @fun.register(Decimal) def fun_num(arg): print(type(arg), arg) if __name__ == '__main__': fun(\u0026quot;Hello, world.\u0026quot;) fun(123) fun(['spam', 'spam', 'eggs', 'spam']) fun(None) fun(1.23) fun(Decimal('1.23')) # False print(fun_num is fun) # To access all registered implementations, use the read-only registry attribute print(fun.registry.keys()) print(fun.registry[float]) print(fun.registry[object]) # 输出结果 # \u0026lt;class 'str'\u0026gt; Hello, world. # \u0026lt;class 'int'\u0026gt; 123 # \u0026lt;class 'list'\u0026gt; ['spam', 'spam', 'eggs', 'spam'] # \u0026lt;class 'NoneType'\u0026gt; None # \u0026lt;class 'float'\u0026gt; 1.23 # \u0026lt;class 'decimal.Decimal'\u0026gt; 1.23 # False # dict_keys([\u0026lt;class 'object'\u0026gt;, \u0026lt;class 'str'\u0026gt;, \u0026lt;class 'int'\u0026gt;, \u0026lt;class 'list'\u0026gt;, \u0026lt;class 'NoneType'\u0026gt;, \u0026lt;class 'decimal.Decimal'\u0026gt;, \u0026lt;class 'float'\u0026gt;]) # \u0026lt;function fun_num at 0x00000155A9E9B790\u0026gt; # \u0026lt;function fun at 0x00000155A972F0D0\u0026gt;  简单应用\n下面的 check_type 是本例附加的限制：两个参数必须是完全相同的类型，并不是 singledispatch 自动完成了多参数分派。列表的 extend 和字典的 update 会修改第一个参数；字符串与元组会返回新对象。如果不希望修改调用者的列表或字典，应先传入副本。\nfrom functools import singledispatch def check_type(func): def wrapper(*args): arg1, arg2 = args[:2] if type(arg1) != type(arg2): return 'Error: 参数类型不同' return func(*args) return wrapper @singledispatch def add(obj, new_obj): raise TypeError(f'不支持的首参数类型: {type(obj).__name__}') @add.register(str) @check_type def _(obj, new_obj): obj += new_obj return obj @add.register(list) @check_type def _(obj, new_obj): obj.extend(new_obj) return obj @add.register(dict) @check_type def _(obj, new_obj): obj.update(new_obj) return obj @add.register(tuple) @check_type def _(obj, new_obj): return *obj, *new_obj if __name__ == '__main__': print(add('hello', ', world')) print(add([1, 2, 3], [4, 5, 6])) print(add({'name': 'xxx'}, {'age': 111})) print(add(('1', '2',), ('3', '4',))) # list 和 字符串 无法拼接 print(add([1, 2, 3], '4,5,6')) # 输出结果 # hello, world # [1, 2, 3, 4, 5, 6] # {'name': 'xxx', 'age': 111} # ('1', '2', '3', '4') # Error: 参数类型不同  可将下面的检查追加到第二个文件。无注册实现的整数应抛出 TypeError；这里明确捕获它，避免把预期异常误当作合并示例失败。\nvalues = [1] assert add(values, [2]) is values assert values == [1, 2] assert add([1], '2') == 'Error: 参数类型不同' try: add(1, 2) except TypeError as error: print(error) # 不支持的首参数类型: int  "},{id:22,href:"/blog/404388560/",title:"Single Dispatch Generic Functions",description:"A Fluent Python example uses functools.singledispatch to generate type-specific HTML for strings, sequences and numeric values, with registered handlers and sample output.",content:"Environment: CPython 3.12.14, standard library only. Save the block as htmlize_demo.py and run python htmlize_demo.py; the commented output shows the expected handlers. Set element order and object representations may vary, so compare the rendered structure rather than relying on their exact printed order.\nsingledispatch chooses an implementation from the first argument\u0026rsquo;s runtime type, not from every argument or from a sequence\u0026rsquo;s item types. Type-annotation registration needs Python 3.7 or newer. The abc.Sequence below comes from collections.abc; it does not use the old collections.Sequence alias, which was removed in Python 3.10.\n\u0026quot;\u0026quot;\u0026quot; from Fluent Python 2nd Example 9-19 \u0026quot;\u0026quot;\u0026quot; from functools import singledispatch from collections import abc import fractions import decimal import html import numbers @singledispatch def htmlize(obj: object) -\u0026gt; str: content = html.escape(repr(obj)) return f'\u0026lt;pre\u0026gt;{content}\u0026lt;/pre\u0026gt;' @htmlize.register def _(text: str) -\u0026gt; str: content = html.escape(text).replace('\\n', '\u0026lt;br\u0026gt;\\n') return f'\u0026lt;p\u0026gt;{content}\u0026lt;/p\u0026gt;' @htmlize.register def _(seq: abc.Sequence) -\u0026gt; str: inner = '\u0026lt;/li\u0026gt;\\n\u0026lt;li\u0026gt;'.join(htmlize(item) for item in seq) return '\u0026lt;ul\u0026gt;\\n\u0026lt;li\u0026gt;' + inner + '\u0026lt;/li\u0026gt;\\n\u0026lt;/ul\u0026gt;' @htmlize.register def _(n: numbers.Integral) -\u0026gt; str: return f'\u0026lt;pre\u0026gt;{n} (0x{n:x})\u0026lt;/pre\u0026gt;' @htmlize.register def _(n: bool) -\u0026gt; str: return f'\u0026lt;pre\u0026gt;{n}\u0026lt;/pre\u0026gt;' @htmlize.register(fractions.Fraction) def _(x) -\u0026gt; str: frac = fractions.Fraction(x) return f'\u0026lt;pre\u0026gt;{frac.numerator}/{frac.denominator}\u0026lt;/pre\u0026gt;' @htmlize.register(decimal.Decimal) @htmlize.register(float) def _(x) -\u0026gt; str: frac = fractions.Fraction(x).limit_denominator() return f'\u0026lt;pre\u0026gt;{x} ({frac.numerator}/{frac.denominator})\u0026lt;/pre\u0026gt;' if __name__ == '__main__': param_list = [ {1, 2, 3}, abs, 'Hello \\n World', 123, ['linux', 1, {1, 2, 3}], True, fractions.Fraction(2, 3), 0.1, decimal.Decimal('0.123456') ] for p in param_list: print(p) print(htmlize(p)) print('\\n') # {1, 2, 3} # \u0026lt;pre\u0026gt;{1, 2, 3}\u0026lt;/pre\u0026gt; # # # \u0026lt;built-in function abs\u0026gt; # \u0026lt;pre\u0026gt;\u0026amp;lt;built-in function abs\u0026amp;gt;\u0026lt;/pre\u0026gt; # # # Hello # World # \u0026lt;p\u0026gt;Hello \u0026lt;br\u0026gt; # World\u0026lt;/p\u0026gt; # # # 123 # \u0026lt;pre\u0026gt;123 (0x7b)\u0026lt;/pre\u0026gt; # # # ['linux', 1, {1, 2, 3}] # \u0026lt;ul\u0026gt; # \u0026lt;li\u0026gt;\u0026lt;p\u0026gt;linux\u0026lt;/p\u0026gt;\u0026lt;/li\u0026gt; # \u0026lt;li\u0026gt;\u0026lt;pre\u0026gt;1 (0x1)\u0026lt;/pre\u0026gt;\u0026lt;/li\u0026gt; # \u0026lt;li\u0026gt;\u0026lt;pre\u0026gt;{1, 2, 3}\u0026lt;/pre\u0026gt;\u0026lt;/li\u0026gt; # \u0026lt;/ul\u0026gt; # # # True # \u0026lt;pre\u0026gt;True\u0026lt;/pre\u0026gt; # # # 2/3 # \u0026lt;pre\u0026gt;2/3\u0026lt;/pre\u0026gt; # # # 0.1 # \u0026lt;pre\u0026gt;0.1 (1/10)\u0026lt;/pre\u0026gt; # # # 0.123456 # \u0026lt;pre\u0026gt;0.123456 (1929/15625)\u0026lt;/pre\u0026gt;  For a quick check, append the following to the same file. It verifies escaping, recursive list dispatch and the separate bool handler (bool is a subclass of int). The decimal/float handler deliberately uses limit_denominator(), so its fraction may be an approximation and need not expose the exact binary representation of a float.\nassert htmlize('\u0026lt;\u0026amp;\u0026gt;') == '\u0026lt;p\u0026gt;\u0026amp;lt;\u0026amp;amp;\u0026amp;gt;\u0026lt;/p\u0026gt;' assert htmlize(True) == '\u0026lt;pre\u0026gt;True\u0026lt;/pre\u0026gt;' assert htmlize(123) == '\u0026lt;pre\u0026gt;123 (0x7b)\u0026lt;/pre\u0026gt;' assert htmlize(['linux', 1]) == ( '\u0026lt;ul\u0026gt;\\n\u0026lt;li\u0026gt;\u0026lt;p\u0026gt;linux\u0026lt;/p\u0026gt;\u0026lt;/li\u0026gt;\\n\u0026lt;li\u0026gt;\u0026lt;pre\u0026gt;1 (0x1)\u0026lt;/pre\u0026gt;\u0026lt;/li\u0026gt;\\n\u0026lt;/ul\u0026gt;' )  "},{id:23,href:"/blog/452409391/",title:"Python何时执行装饰器",description:"结合直接运行与导入 decorator.py 的输出，记录 Python 装饰器在函数定义时执行的时机，并区分装饰器执行、函数注册和被装饰函数调用。",content:"运行环境：CPython 3.12.14，只需标准库。将第一个代码块保存为一个空目录中的 decorator.py，在该目录执行 python decorator.py，即可看到第一组输出。输出里的函数地址每次可能不同，应核对行的顺序和函数名。\n 执行到函数定义语句时，装饰器会接收刚创建的函数对象，并将返回值绑定到函数名；这通常发生在模块首次导入时。被装饰函数的函数体仍要等到调用才执行。本例装饰器只注册并返回原函数，并未在注册时调用 f1() 或 f2()，参见函数定义的官方说明。  # decorator.py decorators = [] def decorator(func): print(f'running decorator {func}') decorators.append(func) return func @decorator def f1(): print('running f1()') @decorator def f2(): print('running f2()') def f3(): print('running f3()') def main(): print('running main()') print('decorators -\u0026gt;', decorators) f1() f2() f3() if __name__ == '__main__': main()  running decorator \u0026lt;function f1 at 0x000002AC46B37550\u0026gt; running decorator \u0026lt;function f2 at 0x000002AC46B55C10\u0026gt; running main() decorators -\u0026gt; [\u0026lt;function f1 at 0x000002AC46B37550\u0026gt;, \u0026lt;function f2 at 0x000002AC46B55C10\u0026gt;] running f1() running f2() running f3()  2. 当 decorator.py 被导入，而不是作为脚本运行\n下面的代码在同一目录内另存为 import_demo.py，用一个新的 Python 进程执行 python import_demo.py。不能将它追加到 decorator.py 自身，否则脚本会再以模块名加载一遍，混淆这两种运行方式。\nimport decorator print(decorator.decorators) assert [func.__name__ for func in decorator.decorators] == ['f1', 'f2'] # running decorator \u0026lt;function f1 at 0x000001BBC3585C10\u0026gt; # running decorator \u0026lt;function f2 at 0x000001BBC3586310\u0026gt; # [\u0026lt;function f1 at 0x000001BBC3585C10\u0026gt;, \u0026lt;function f2 at 0x000001BBC3586310\u0026gt;]  导入时会执行注册语句，但 if __name__ == '__main__' 不成立，所以不会运行 main()。在同一进程中再次普通 import decorator 通常会复用 sys.modules 中的模块，不会再次执行装饰器；这里用新进程来对照首次导入的输出。\n"},{id:24,href:"/blog/4119532816/",title:"Function Parameters as References",description:"A Python example from Fluent Python compares += on numbers, lists and tuples passed as arguments, showing how mutation differs from rebinding a local parameter.",content:"This example uses only the standard library and was checked with CPython 3.12.14. Save the complete block as references.py and run python references.py; each call prints its return value followed by the original arguments.\nPython passes arguments by assignment: the parameter initially refers to the same object as the caller\u0026rsquo;s argument. Rebinding a local parameter does not rebind the caller\u0026rsquo;s variable. Mutating a shared list does change the object both names refer to, as explained in the Python FAQ.\n\u0026quot;\u0026quot;\u0026quot; from Fluent Python 2nd Example 6-11 \u0026quot;\u0026quot;\u0026quot; def f(p1, p2): p1 += p2 return p1 x, y = 1, 2 print(f(x, y)) print(x, y) # 3 # 1 2 a = [1, 2] b = [3, 4] print(f(a, b)) print(a, b) # [1, 2, 3, 4] # [1, 2, 3, 4] [3, 4] m = (1, 2) n = (3, 4) print(f(m, n)) print(m, n) # (1, 2, 3, 4) # (1, 2) (3, 4)  For these built-in types, += extends the list in place, while integers and tuples produce a new result that is assigned to the local name p1. The return value therefore differs from the caller\u0026rsquo;s unchanged number or tuple. Other classes can define their own augmented-assignment behavior.\n"},{id:25,href:"/blog/2414890336/",title:"List, Tuple, += 问题记录",description:"通过嵌套列表与元组中的可变列表示例，记录重复引用、原地加法和下标赋值的差异，并结合 dis 字节码观察 += 引发异常时对象仍被修改的现象。",content:"运行环境：以下示例使用标准库，在 CPython 3.12.14 验证。每个代码块可独立保存为 demo.py 后执行 python demo.py；其中 TypeError 是要观察的预期行为，示例会捕获它以继续打印对象状态。\nBuilding Lists of Lists test_1 = [['1'] * 3 for i in range(3)] test_2 = [['1'] * 3] * 3 test_1[1][1] = 0 print(test_1) # [['1', '1', '1'], ['1', 0, '1'], ['1', '1', '1']] test_2[1][1] = 0 print(test_2) # [['1', 0, '1'], ['1', 0, '1'], ['1', 0, '1']] print(test_1[0] is test_1[1], test_2[0] is test_2[1]) # False True  列表推导式每次创建一个新的内层列表；[inner] * 3 重复的是对同一个内层列表的引用。这里用 print 观察结果，而不是把预期结果重新赋值给变量。\nTuple, += a = (1, 2, [3, 4]) try: a[2] += [5, 6] except TypeError as error: print(f'TypeError: {error}') # TypeError: 'tuple' object does not support item assignment print(a) # (1, 2, [3, 4, 5, 6])  += 对这里的列表先做原地扩展，再尝试把结果写回 a[2]。后一步因元组不支持下标赋值而失败，但前一步已修改的列表不会自动恢复；元组不可变也不表示其中引用的列表不可变。这个现象见 Python 官方 FAQ。\n直接调用列表方法不需要给元组的槽位重新赋值，不过 append 和 extend 的结果不同：\na = (1, 2, [3, 4]) a[2].append([5, 6]) print(a) # (1, 2, [3, 4, [5, 6]]) a = (1, 2, [3, 4]) a[2].extend([5, 6]) print(a) # (1, 2, [3, 4, 5, 6])  append 将整个参数作为一个元素加入，extend 逐个加入参数中的元素，参见可变序列操作。\n可以用下面的独立代码查看这两种写法的字节码：\nimport dis dis.dis('a[2] += [5, 6]') print() dis.dis('a[2].append([5, 6])')  在 CPython 3.12 中，第一个反汇编的 BINARY_OP (+=) 在 STORE_SUBSCR 之前；第二个通过 CALL 调用 append，没有对元组执行 STORE_SUBSCR。dis.dis 只反汇编传入的代码，不会执行这两条语句。字节码是 CPython 实现细节，不同版本的指令和偏移量会变化，应以本机 dis 输出为准。\n"},{id:26,href:"/blog/2243409341/",title:"Hugo 添加评论功能",description:"记录为 Hugo 博客接入 utterances 评论的配置方法，包括安装 GitHub App、在文章模板中加载评论脚本，以及设置仓库、评论关联规则和主题。",content:"Hugo 添加评论功能 适用范围：这是 2021 年 Doks 旧版模板中的 utterances 接入方式，本站 Doks 0.2.3 项目仍使用 layouts/blog/single.html 与 config/_default/config.toml。其他主题或新版 Doks 应先核对自己的文章模板位置，不要直接覆盖整个模板。以下参数按 utterances 官方配置核对；本次校订没有发布评论或创建 Issue。\nutterances 用 GitHub Issues 保存评论。先准备一个公开的 GitHub 仓库，启用 Issues（fork 的仓库也要检查），再把 utterances GitHub App安装到该仓库，并确认安装授权范围包含它。仓库可以专门用于评论，不必和网站源码相同；私有仓库不适合这里的公开评论读取方式。\n  完成上述仓库、Issues 和 App 安装前提，记录仓库的 owner/repo，例如下面的 owner/comments-repo 只是占位值，必须换成自己的仓库。\n  在 layouts/blog/single.html 的文章内容之后添加评论脚本，保留主题原有布局。下面的 utteranc 是本站使用的配置键名，需与下一步 TOML 保持一致：\n{{ define \u0026quot;main\u0026quot; }} \u0026lt;div class=\u0026quot;row justify-content-center\u0026quot;\u0026gt; \u0026lt;div class=\u0026quot;col-md-12 col-lg-10 col-xl-8\u0026quot;\u0026gt; \u0026lt;article\u0026gt; \u0026lt;div class=\u0026quot;blog-header\u0026quot;\u0026gt; \u0026lt;h1\u0026gt;{{ .Title }}\u0026lt;/h1\u0026gt; {{ partial \u0026quot;main/blog-meta.html\u0026quot; . }} \u0026lt;/div\u0026gt; \u0026lt;p class=\u0026quot;lead\u0026quot;\u0026gt;{{ .Params.lead | safeHTML }}\u0026lt;/p\u0026gt; {{ .Content }} \u0026lt;/article\u0026gt; \u0026lt;/div\u0026gt; \u0026lt;/div\u0026gt; \u0026lt;!-- 添加评论 --\u0026gt; {{ if .Site.Params.utteranc.enable }} \u0026lt;script src=\u0026quot;https://utteranc.es/client.js\u0026quot; repo=\u0026quot;{{ .Site.Params.utteranc.repo }}\u0026quot; issue-term=\u0026quot;{{ .Site.Params.utteranc.issueTerm }}\u0026quot; theme=\u0026quot;{{ .Site.Params.utteranc.theme }}\u0026quot; crossorigin=\u0026quot;anonymous\u0026quot; async\u0026gt; \u0026lt;/script\u0026gt; {{ end }} {{ end }}    在 config/_default/config.toml 中合并配置；若已有 [params.utteranc]，修改现有表，不要重复定义同名表：\n# 添加配置 [params.utteranc] enable = true repo = \u0026quot;owner/comments-repo\u0026quot; # 替换为已授权的公开仓库 issueTerm = \u0026quot;title\u0026quot; theme = \u0026quot;github-light\u0026quot;  issueTerm = \u0026quot;title\u0026quot; 会按文章标题查找对应 Issue，因此文章重名或后续改标题会影响关联。新站也可选择 pathname 按路径关联；已有评论的站点不要随意改规则，应先核对现有 Issue 的对应关系。theme 可按官方配置选择，示例保留 github-light。\n  验证加载，不发送测试评论\n本地按本站脚本运行 npm run server，打开一篇文章，查看生成的页面源码是否包含自己的 repo、预期的 issue-term 和评论脚本。浏览器需允许 utteranc.es/client.js 及其 iframe 加载；若页面不显示，检查开发者工具的网络和控制台记录，再核对仓库公开状态、Issues、App 授权范围及浏览器拦截规则。\n部署后同样打开文章核对评论区域和已有 Issue 的关联。还没有对应 Issue 的新文章，不会仅因浏览页面就立即创建 Issue；通常在首次实际评论时才由机器人创建。读者提交评论时需要 GitHub 登录和授权，或直接前往对应 GitHub Issue 评论，见官方工作原理。这些读取检查无需发送评论，也不应把评论写入示例作者的仓库。\n  "},{id:27,href:"/blog/3716962172/",title:"装饰器",description:"通过 Python 示例整理普通函数装饰器、带参数装饰器与类装饰器的写法，涉及返回值、定时任务包装，以及在类中定义和使用装饰器。",content:"运行环境：以下独立代码块在 CPython 3.12.14 验证；除定时任务一节外只使用标准库。将某一完整代码块保存为 demo.py，用 python demo.py 运行，对照末尾的输出注释。\n普通装饰器的第一个例子只打印日志；第二个例子通过 return ret 保留被装饰函数的返回值。实际封装时还可用 functools.wraps 保留函数名称、文档等元数据。\n装饰器   普通装饰器 def logger(func): def wrapper(*args, **kwargs): func_name = func.__name__ print(f'执行了 {func_name} 函数') func(*args, **kwargs) print(f'{func_name} 函数执行完成') return wrapper @logger def add(x, y): print(f'{x} + {y} = {x + y}') add(1, 2) # 执行了 add 函数 # 1 + 2 = 3 # add 函数执行完成  def logger(func): def wrapper(*args, **kwargs): func_name = func.__name__ print(f'执行了 {func_name} 函数') ret = func(*args, **kwargs) print(f'{func_name} 函数执行完成') return ret return wrapper @logger def add(x, y): print(f'{x} + {y} = {x + y}') return x + y add_res = add(1, 2) print(add_res) # 执行了 add 函数 # 1 + 2 = 3 # add 函数执行完成 # 3    定时执行任务装饰器 本节另需安装 schedule；验证使用的是 schedule==1.2.2，可运行 python -m pip install schedule==1.2.2。请在独立脚本中运行，下面的演示窗口为 3.2 秒，结束后清理本例注册的任务，不会一直占用终端。\n@repeat 在函数定义时注册任务，外层 @run_every 返回的包装函数负责启动轮询；这里的任务不接收参数。调度不是实时保证，运行次数会受任务耗时和系统调度影响；正常空闲环境下可观察到约每秒一次的三行输出。长任务、并行任务和精确计时需另行设计，参见 Schedule 官方示例。\nimport functools import time import schedule from schedule import every, repeat def run_task(duration=3.2): \u0026quot;\u0026quot;\u0026quot; 定时执行任务 :return: \u0026quot;\u0026quot;\u0026quot; deadline = time.monotonic() + duration while time.monotonic() \u0026lt; deadline: schedule.run_pending() time.sleep(0.05) def run_every(func): @functools.wraps(func) def wrapper(*args, **kwargs): try: run_task() except Exception: print('任务执行出错啦') raise finally: schedule.clear('decorator-demo') return wrapper @run_every @repeat(every(1).seconds.tag('decorator-demo')) def test(): print('hello world') test() # hello world # hello world # hello world    带参数的装饰器 import functools def run_every(param): \u0026quot;\u0026quot;\u0026quot; 带参数的普通装饰器 :param param: :return: \u0026quot;\u0026quot;\u0026quot; def decorator(func): @functools.wraps(func) def wrapper(*args, **kwargs): print(f'{param=}') return func(*args, **kwargs) return wrapper return decorator @run_every('你好') def test(): print('hello world') test() # param='你好' # hello world    不带参数的类装饰器 class logger(object): def __init__(self, func): self.func = func def __call__(self, *args, **kwargs): func_name = self.func.__name__ print(f'执行了 {func_name} 函数') ret = self.func(*args, **kwargs) print(f'{func_name} 函数执行完成') return ret @logger def test(): print('test()') ret_print = test() print(ret_print) # 执行了 test 函数 # test() # test 函数执行完成 # None    带参数的类装饰器 class logger(object): def __init__(self, level='INFO'): self.level = level def __call__(self, func): def wrapper(*args, **kwargs): func_name = func.__name__ print(f'{self.level} 日志等级') print(f'执行了 {func_name} 函数') ret = func(*args, **kwargs) print(f'{func_name} 函数执行完成') return ret return wrapper @logger(level='DEBUG') def test(): print('test()') ret_print = test() print(ret_print) # DEBUG 日志等级 # 执行了 test 函数 # test() # test 函数执行完成 # None    将装饰器定义为类的一部分 from functools import wraps class A: # 装饰器作为实例方法 def decorator1(self, func): @wraps(func) def wrapper(*args, **kwargs): print('Decorator 1') return func(*args, **kwargs) return wrapper # 装饰器作为类方法 @classmethod def decorator2(cls, func): @wraps(func) def wrapper(*args, **kwargs): print('Decorator 2') return func(*args, **kwargs) return wrapper a = A() @a.decorator1 def test1(): pass @A.decorator2 def test2(): pass test1() test2() # Decorator 1 # Decorator 2    "},{id:28,href:"/blog/2726440838/",title:"使用 Hugo + Github + Doks 搭建个人网站",description:"记录使用 Hugo 和 Doks 搭建个人网站的步骤，涵盖主题安装、本地预览、博客文章创建及 GitHub Pages 自动部署，并整理模板定制和构建问题。",content:"使用 Hugo + Github + Doks 搭建个人网站 本文保留 2021 年 Doks 旧版项目的搭建思路，本站依赖文件中的主题版本为 Doks 0.2.3，不代表新版 Doks 的安装教程。原先的 Node.js 15、ubuntu-18.04 和旧版 Actions 配置属于历史环境；Node.js 15 已结束维护，见 Node.js 版本状态。新建项目应按所选版本的 Doks 文档和 Hugo 文档选择相容的工具链。\n下面的命令需在项目根目录执行。复现已有站点时以仓库的 package.json、package-lock.json 和工作流为准；记录 node --version、npm --version、hugo version，不要直接混用不同年代的主题与依赖。本次校订核对了仓库脚本和配置，没有重新执行安装、构建或部署。\n1. 安装 Hugo, 参阅官方文档 2. 选择合适的主题 3. 安装主题，选择与版本对应的方式 以下是 2021 年使用的历史克隆来源，二选一。远端默认分支可能已经升级；它们不保证现在克隆出来仍是 Doks 0.2.3。复现旧项目应使用已知提交和锁文件，新项目应使用对应版本的官方安装步骤。\n  Hugo网站的Doks主题: Huog-Doks-Theme\n  Doks官网: Doks\n  # 历史来源：Doks child theme git clone https://github.com/h-enk/doks-child-theme.git my-doks-site \u0026amp;\u0026amp; cd my-doks-site    # 历史来源：Doks starter theme git clone https://github.com/h-enk/doks.git my-doks-site \u0026amp;\u0026amp; cd my-doks-site    # 已有 package-lock.json 的项目按锁文件安装 npm ci    # Start development server # 本站旧项目可用的预览脚本；服务地址以终端输出为准 npm run server    4. 参照所选主题的文档, 自定义修改样式 5. 以 Doks 为例   添加 blog 文章\n# 本站旧版脚本的两种等价方式，选择一条执行 npm run create -- \u0026quot;blog/my-first-post/index.md\u0026quot; # 或者： hugo new \u0026quot;blog/my-first-post/index.md\u0026quot;    编写博客文件, 完成之后, 注意事项\n# 在新文章的 frontmatter 中取消草稿形式 draft: false    预览效果\nnpm run server    发布到Github\n  GitHub 上建立 {username}.github.io 仓库，username 替换为自己的账号。项目站点的地址和 baseURL 与用户站点不同，按 GitHub Pages 文档配置发布来源。\n  工作流参考本站维护的 .github/workflows/deploy-github.yml。校订时它监听 main，执行锁文件安装、检查、构建和静态输出验收，再把 public 发布到 gh-pages；GitHub Pages 的发布分支应与实际产物分支相符。该文件仍包含为旧项目兼容而保留的工具版本，不应作为新项目的版本推荐。新项目可参考 Hugo 官方 GitHub Pages 部署指南，不要把它的直接 Actions 发布方式与 gh-pages 分支方式混在一起。\n  源码分支、工作流触发分支和推送分支保持一致。本例统一为 main；如果自己的仓库使用别的分支，应同步修改工作流，而不是一边监听 master、一边推送 main。\n  先检查仓库状态。旧版 Doks 的 npm run init 实际包含 rimraf .git，会删除现有 Git 元数据，已有项目不要执行它。下面的初始化命令只用于尚无 Git 仓库的新目录，git init -b main 要求 Git 2.28 或更高版本，见 Git 官方说明。\n# 仅在尚无 Git 仓库的新项目根目录中初始化 git init -b main git add . git commit -m \u0026quot;First Commit\u0026quot; # 将 owner 和仓库名替换成自己的远程仓库 git remote add origin https://github.com/owner/owner.github.io.git git remote -v git push -u origin main  如果目录来自 git clone，它已经是 Git 仓库，应跳过 git init；先用 git status、git branch --show-current 和 git remote -v 检查状态。已有 origin 时按需用 git remote set-url origin 自己的仓库地址 修改，不要再次添加同名远程，也不要删除 .git。\n    验证发布结果\n本地先按仓库脚本检查并构建，确认预览中的首页、文章和资源能加载；推送后在 GitHub Actions 中核对对应提交的工作流是否成功，再检查 Pages 部署状态。最后打开 https://{username}.github.io/，核对新文章、CSS/JS 和站内链接。仅看到一次本地预览成功，不等于线上已发布；失败时先看具体步骤日志，不要反复改依赖碰运气。\n  6. 个人修改项, 仅供参考   修改博客默认生成的模板, archetypes/blog.md\n# 修改之后，以下是 Hugo archetype 模板内容 --- title: \u0026quot;{{ replace .Name \u0026quot;-\u0026quot; \u0026quot; \u0026quot; | title }}\u0026quot; description: \u0026quot;\u0026quot; lead: \u0026quot;\u0026quot; date: {{ .Date }} lastmod: {{ .Date }} draft: false weight: 50 contributors: [作者名字] ---    7. 问题记录   rimraf not found：先确认在正确的项目目录，并按原锁文件执行 npm ci。rimraf 已在本站 devDependencies 中，省略开发依赖的生产安装会导致构建工具缺失；不应在依赖没有装全时靠删除 .git 或盲目全局安装解决。\n  POSTCSS: failed to transform \u0026quot;main.css\u0026quot;：保留完整报错，检查是否安装了主题要求的 Hugo Extended 及匹配的本地 PostCSS 依赖。可用 npm ls postcss postcss-cli autoprefixer 核对已安装版本，再针对错误修复；全局安装 postcss-cli 不保证被项目构建调用。旧文中的 npm audit fix 会改变依赖树，不作为通用构建修复命令，更新依赖应另行审查锁文件并验证。\n  "},{id:29,href:"/blog/hello-world/",title:"Hello World",description:"A minimal Hello World post containing two Python import examples: import this and import __hello__.",content:"Hello World import this import __hello__  "},{id:31,href:"/tools/curl-to-requests/",title:"cURL 转 Python requests",description:"将常见 cURL 命令转换为 Python requests 代码，支持请求头、Cookie、JSON 请求体和查询参数，提供 GET、POST 示例与使用说明。",content:"使用方法  粘贴一条以 curl 开头的命令，例如浏览器开发者工具 Network 面板中“Copy as cURL”复制的请求。 点击“转换”，在右侧查看生成的 Python requests 代码。 点击“复制”，检查请求地址、请求头、认证和请求体，再放入已安装 requests 的 Python 环境中运行。  页面只生成代码，点击“转换”不会向命令中的目标地址发送请求。运行生成的 Python 代码才会发出 HTTP 请求；Requests 的安装和 API 用法见 官方快速入门。\n示例：带请求头的 GET 输入：\ncurl 'https://example.com/api/messages?limit=2' -H 'Accept: application/json'  结果会保留 URL 和 Accept 请求头，并生成 requests.get(...) 调用。这里的 example.com 是示例地址，可替换为你实际需要访问的接口。\n示例：发送 JSON 的 POST 输入：\ncurl 'https://example.com/api/messages' \\ -H 'Content-Type: application/json' \\ --data-raw '{\u0026quot;name\u0026quot;:\u0026quot;CLANNAD\u0026quot;,\u0026quot;favorite\u0026quot;:true}' \\ --max-time 10  输出：\nimport requests url = \u0026quot;https://example.com/api/messages\u0026quot; headers = { \u0026quot;Content-Type\u0026quot;: \u0026quot;application/json\u0026quot;, } payload = { \u0026quot;name\u0026quot;: \u0026quot;CLANNAD\u0026quot;, \u0026quot;favorite\u0026quot;: True, } response = requests.post( url, headers=headers, json=payload, timeout=10, ) print(response.status_code) print(response.text)  JSON 中的 true 已转换为 Python 的 True；识别为 JSON 的请求体通过 json=payload 传入。\n支持范围与常见问题  支持单个请求地址、常见 HTTP 方法、-H 请求头、-b Cookie 字符串、-u 基本认证、常见 --data 参数及 --json。 -G 搭配数据参数会生成查询参数；--max-time 或 --connect-timeout 会转换为 Requests 的 timeout 参数，两者的实际超时语义并不完全相同。 暂不支持 -F 文件上传或 @文件名 读取请求体。遇到未支持的选项、缺失 URL 或未闭合引号时，会提示错误，需调整命令后再转换。 转换覆盖常见用法，不能保证所有 cURL 选项与 Requests 行为完全相同；例如部分显示和传输选项不会出现在输出中。转换后应结合接口要求检查代码。  相关工具 JSON 格式化 · Unix 时间戳转换 · 返回工具箱\n"},{id:32,href:"/tools/json-formatter/",title:"JSON 格式化工具",description:"在线格式化 JSON、JSON5 和常见 Python Dict，转换为带缩进与语法高亮的标准 JSON，支持复制结果并提示解析错误。",content:"使用方法  将待处理的数据粘贴到“原始 JSON”输入框。 点击“格式化”，在结果区查看两空格缩进和语法高亮后的 JSON。 点击“复制”获取结果；如果输入不完整或语法有误，输入框下方会显示解析错误，修改后可重新格式化。  解析和格式化在浏览器中完成。输入框支持标准 JSON，也支持 JSON5 的单引号、未加引号的标识符键、注释和尾随逗号，语法说明可参阅 JSON5 官方文档。\n示例：格式化标准 JSON 输入：\n{\u0026quot;name\u0026quot;:\u0026quot;CLANNAD\u0026quot;,\u0026quot;episodes\u0026quot;:23,\u0026quot;favorite\u0026quot;:true}  输出：\n{ \u0026quot;name\u0026quot;: \u0026quot;CLANNAD\u0026quot;, \u0026quot;episodes\u0026quot;: 23, \u0026quot;favorite\u0026quot;: true }  示例：常见 Python 字典写法 输入中的 True、False、None 会转换为 JSON 的 true、false、null；数字键会转换为字符串键。\n{'name': 'CLANNAD', 'favorite': True, 'note': None, 1: '第一季'}  输出：\n{ \u0026quot;1\u0026quot;: \u0026quot;第一季\u0026quot;, \u0026quot;name\u0026quot;: \u0026quot;CLANNAD\u0026quot;, \u0026quot;favorite\u0026quot;: true, \u0026quot;note\u0026quot;: null }  适用范围 这里处理的是数据字面量，不会执行 Python 或 JavaScript 表达式，也不支持 Python 的元组、集合和函数调用。格式化会移除注释、统一引号与缩进，并可能调整数字键的顺序。\n数字使用 JavaScript 数值精度；需要完整保留的长整数编号应使用字符串。JSON5 中的 NaN、Infinity 经标准 JSON 序列化会成为 null，因此不适合用本工具无损保存这些特殊数值。\n相关工具 cURL 转 Python requests · Unix 时间戳转换 · 返回工具箱\n"},{id:33,href:"/tools/timestamp/",title:"Unix 时间戳转换工具",description:"在线转换 Unix 秒、毫秒时间戳与日期时间，支持时区选择、ISO 8601、批量转换及 CSV 导出，附 Asia/Shanghai 与 UTC 示例。",content:"使用方法  输入 Unix 时间戳，选择“自动识别”“秒”或“毫秒”，结果会随输入更新。 按需选择时区，例如 Asia/Shanghai、UTC，或输入 browser 使用浏览器本地时区。 查看 Unix 秒、毫秒、ISO 8601、所选时区的时间和相对时间，点击对应“复制”按钮获取结果。 也可以修改日期与时间，将该时区下的本地时间反向转换为时间戳；“填入当前”会使用当前时刻。  Unix 时间戳以 UTC 的 1970 年 1 月 1 日为起点；切换时区会改变同一时刻的显示方式。JavaScript 日期使用毫秒表示时间，相关背景见 MDN Date 文档。\n示例：秒、毫秒与时区 选择时区 Asia/Shanghai，输入以下任一数值，都表示同一个时刻：\n1704067200 （秒） 1704067200000 （毫秒）  两行仅用于对照；在单个转换的输入框中，每次粘贴一个数值，不包含括号内的单位说明。\n预期结果：\n   输出项 结果     Unix 秒 1704067200   Unix 毫秒 1704067200000   ISO 8601 2024-01-01T00:00:00.000Z   Asia/Shanghai 2024-01-01 08:00:00 UTC+08:00   UTC 2024-01-01 00:00:00 UTC+00:00    时间戳 0 对应 1970-01-01T00:00:00.000Z，在上海时区显示为同日 08:00:00。自动识别适合常见的秒、毫秒数值；历史日期或特殊范围应手动指定单位，以免按数值大小判断时产生歧义。\n批量转换示例 切换到“批量转换”，每行输入一个时间戳，或不带时区后缀的日期时间。日期时间按上方所选时区解释，一次最多处理 500 个非空行。\n1704067200 1704067200000 2024-01-01 08:00:00  选择 Asia/Shanghai 后，前两行会转换为 2024-01-01 08:00:00 UTC+08:00；第三行会转换为 1704067200 s / 1704067200000 ms。\n点击“转换”查看每行的成功或失败状态。“复制结果”仅复制成功的转换，“导出 CSV”保留各行结果与错误信息，便于检查未能解析的输入。\n时区与输入说明 使用 IANA 时区名称，例如 Asia/Shanghai 或 America/New_York，不要把日期本身的显示时间误认为 UTC。日期时间反向转换按秒处理；毫秒精度可直接通过时间戳输入保留。\n无效时区、超出日期范围或不符合格式的输入会提示错误。夏令时切换造成不存在的本地时间时会报错；同一本地时间对应两个时刻时，会选择较早的一个并显示提示。相对时间基于当前时刻计算，随着时间变化会有所不同。\n相关工具 JSON 格式化 · cURL 转 Python requests · 返回工具箱\n"},{id:34,href:"/tools/",title:"在线工具箱",description:"提供 JSON 格式化、cURL 转 Python requests、Unix 时间戳转换，以及命名转换、密码生成、图片预览和代理检测工具。",content:"选择工具  JSON 格式化：整理 JSON、JSON5 和常见 Python 字典，查看语法高亮结果与解析错误。 cURL 转 Python requests：将常见 HTTP 请求命令转为 Python 代码，附 GET 和 JSON POST 示例。 Unix 时间戳转换：转换秒、毫秒与日期时间，切换时区，批量处理并导出 CSV。  每个工具都有独立地址、使用说明和示例。命名转换、密码生成、图片预览和代理检测仍可从侧边栏打开；下方保留原有 JSON 快捷操作区。\n"}];b.add(c),userinput.addEventListener('input',e,!0),suggestions.addEventListener('click',f,!0);function e(){var g=this.value,e=b.search(g,5),f=suggestions.childNodes,h=0,i=e.length,c;for(suggestions.classList.remove('d-none'),e.forEach(function(b){c=document.createElement('div'),c.innerHTML='<a href><span></span><span></span></a>',a=c.querySelector('a'),t=c.querySelector('span:first-child'),d=c.querySelector('span:nth-child(2)'),a.href=b.href,t.textContent=b.title,d.textContent=b.description,suggestions.appendChild(c)});f.length>i;)suggestions.removeChild(f[h])}function f(){while(suggestions.lastChild)suggestions.removeChild(suggestions.lastChild);return!1}})()